/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20140224-9","meetingId":"h26-cm02","date":"2014年2月24日","dateIso":"2014-02-24","committee":"文教委員会","time":"午前１０時００分～午後０時３７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第１７号議案 品川区青少年問題協議会条例の一部を改正する条例","agenda":"の第１７号議案 品川区青少年問題協議会条例の一部を改正する条例","exchanges":[{"speaker":"本多委員","kind":"質問","question":"５８人以内ということで、会長は１人に入るのかどうかのカウントですが、会長のほかに５８人なのか、会長のほかに５７人なのか。それと、副会長については特に記載がないので、委員から選出というふうに思えばいいのか。その２点を教えてください。","respondent":"福島青少年育成課長","answer":"それで、全部で５６人が現在の会員としてやっています。副会長につきましては、委員の互選ということではありますけれども、副会長をもって充てるというような形で、今までずっと青少年問題協議会としては行ってまいりました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"」ということなので、必然的に品川区の青少年問題協議会も、会長は法律にのっとって区長が就任してきたということなんですが、法改正になって、まあ、わからなくもないんですけれど、今のやり方のほうが自然かなとは思うんですけれども、ほかの区長以外の方を充てようという検討というのはあったのかどうか、またそういう考え方というのはどうなのか、そのあたりをちょっと教えてください。","respondent":"福島青少年育成課長","answer":"当然この改正に当たりまして、会長をどうするかという検討はもちろんしました。ただ、こちらの青少年問題協議会は歴史も長いですし、ずっと区長が会長として行ってまいりました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ教えてください。今は違うのだったらそれはそれでいいんですけれど。そのあたりは、報告を求めて事務局としてはされていると思うんですけれど、どういう角度でどういうふうな議論が必要かというふうに思っているのか、そのあたりを教えてください。","respondent":"福島青少年育成課長","answer":"委員の変更ですけれども、例えば東京保護観察所の品川担当観察官が規定上なっていますけれども、これについては削除する予定です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"高橋委員","kind":"質問","question":"この改正は、やはり地域のいろいろな状況というのがある中で、地域の属性というんでしょうか、そういうものを考えながら、特に委員の方々を、今少しありましたけれど、決めていっているようですが、この品川区という地域での青少年育成の独自性というか、そういったことを発揮するために、今は外される委員の方の話ですけれど、こういう方に新たに入っていただけると。","respondent":"福島青少年育成課長","answer":"こちらにつきましては、やはり子育て環境の変化というのも大きいですし、現在の子育ての諸問題について、子ども・子育て会議ではいろいろな意見を聞いていますので、その委員の方から出していただけますと。","voiceIndex":11,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"すみません、賛成と表明はしたんですけれど、地方分権の流れの中で法律が改正されて、それぞれの地方でやっていくということになったんですが、それはそれで地方分権ということは全然否定しないし、地方のいろいろな状況が一律にやられるよりは、反映できていいのではないかと思うんですけれども、今、国の流れが非常に、とりわけ子どもの教育に対して、例えばいじめの問題で法律をつくって締めつけて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-005"}]},{"id":"topic-02","title":"の第１８号議案 品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例","agenda":"の第１８号議案 品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"仕事量が増えるということでの値上げということですが、大体１日当たり、今までの通例では午前なり、午後なり、２時間とかいう時間で会議を開いて、いろいろなご意見を伺ってきたと思うんですけれど、そのボリュームというのはどの程度のことを考えているのか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただ、１回目、そして特に２回目なのですが、資料のほうを事前にお渡ししまして、課題についても事前にご質問していただくということで、２０名の委員がいらっしゃいますので、事前に読み込んでいただきまして事務局のほうにご提出いただき、それを委員会運営に反映することで。","voiceIndex":27,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"事前の準備の時間がやはりかかるということが主かなと思いますけれど、全然この条例を否定するものではないんですけれども、賛成はしていきたいと思ってはいるんですけれど、１回の会議にあれもこれも盛り込むのではなくて、法律とか条例制定とか、そういう時間的な関係があれば、あれもこれもになるのは当然だと、そこは理解しているんですけれども、１回の会議にあれもこれもと持ち込むのではなくて。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これまでも事前の正副会長との打ち合わせを通して、今後とも会議の運営につきましては、事務局として今のご意見を踏まえながら、ご相談していきたいと考えております。","voiceIndex":29,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"負担増に応じて報酬額を適正にアップするということ自体は全然賛成なんですけれど、なぜ負担が増えたかというところで少し詳しくお伺いしたいんですが。国の子ども・子育て会議が進む中で、当初予定された審議内容が増加するということで、もう少し具体的に、どういったところが当初の想定以上に出てきたところなのか、お伺いしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"このような観点は、今までは任意記載事項ということで、今は項目しか支援事業計画に挙げていないんですけれども、今後そこの部分も踏まえて、大きく支援事業計画をつくっていかなければいけないというふうに認識しております。","voiceIndex":31,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"なかなか、一つ一つ外せない項目というか、今お伺いする中でもなかなか大変な議論が必要かなと思いますけれども、スケジュール的に再来年度、平成２７年度という尻尾が切られている中で、スケジュール的な見通しとして特段課題となるようなところは、今のところはないということでよろしいですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"支援事業計画の策定に当たりましては、今年の３月末までにまず量の見込みを東京都に報告、そしてまた私どもは今、東京都のほうから９月ごろまでに一旦確保方策について一定の報告、そして品川区としてもパブリックコメントを１１月にお願いしようと考えておりますけれども。","voiceIndex":33,"id":"exchange-009"},{"speaker":"高橋委員","kind":"質問・要望","question":"ちょっとわからないので教えていただきたいんですが。条例が変わると当然予算上、今年度も会議があるとすると、その予算的にどのような措置をして、平成２６年度の予算の案が出ていますけれど、平成２６年度の分についてもきっと同じようなことになるかと思いますが、どういうふうにするんでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちら、附属機関の構成員の報酬および費用弁償に関する条例の一部改正条例の附則のところにあるとおり、この条例は４月１日から施行するということで、議案をご審議いただき、その予算がご可決いただきましたら、平成２６年度以降の会議に施行していきたいと考えております。","voiceIndex":35,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどの質疑を聞いていて質問したくなったんですが、パブリックコメントを今年の１１月に予定しているという、再来年度に向けてのあれですから、時期的にはそういうことになるかなとは思うんですけれど、どのぐらいの期間、パブリックコメントを設定するのか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに広報、周知ですが、今申し上げたとおり来年度、パブリックコメントをかける前に、計画案のほうを会議の中で２回ほど検討していただけないかということで、事務局のほうは今、当初の子ども・子育て会議条例のほうにも資料をつけさせていただきましたけれども。","voiceIndex":37,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"期間は最大３０日だと思うんですね。ぜひそういう、最大限入れていただきたいということを、ちょっとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-012"}]},{"id":"topic-03","title":"の第２８号議案 品川区立図書館設置条例の一部を改正する条例","agenda":"の第２８号議案 品川区立図書館設置条例の一部を改正する条例","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"３.制度導入の、(3)の経費負担の軽減なんですけれども、概要でいいので、今まではこのぐらいの経費があったけれども、このぐらい差があるだろうとか、当然プロポーザルとか、その業者が数字をこれから出してくるわけですから、正確な数字が出ないのは当然ですが、例えば概略何％下がるとか、その辺を見込んでいるとか、その辺を教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"こちらにつきましては、９館ありますが、３館ごとに一つのグループとさせていただきまして、そのグループに対して、一つのグループだけ申し込んでいただいても結構ですし、２グループ、３グループ、全て申し込んでいただいても結構ですという公募で、検討しています。","voiceIndex":53,"id":"exchange-013"},{"speaker":"本多委員","kind":"確認","question":"最後に一つだけですけれども、新旧対照表で見ると、「設置」という文言が消えたと先ほど説明があって、現在は新しく新館を設置する計画が、現在はないと思うんですが、例えば将来、新設したいといったとき、今度の新しい条例のままで設置ができるのか、その確認だけしたいんですけれど。","respondent":"中元品川図書館長","answer":"今回の条例で、設置のほうもできます。可能です。","voiceIndex":55,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"これまでの経過ということでそれぞれご説明いただいたんですが、この時期と同じでいいですから、職員の削減が何年に何人ぐらいというのを教えていただきたいというのが一つです。それと、指定管理者制度は全国的にも導入ということになってきて、図書館に限らずなんですが、とりわけ図書館で、全国的にはどのぐらい導入が進んでいるのかというところをお伺いしたいと思います。","respondent":"中元品川図書館長","answer":"その後、平成１６年度から平成１７年度で２１人の削減です。その後、平成１７年度から平成２３年度で１６人の削減です。平成２３年度から平成２５年度で比較いたしますと、７人の削減となっています。全国の図書館の指定管理者の導入状況ですが、６％です。","voiceIndex":57,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ただでさえ導入が少ないのに、当初の目的が……、そこも少ないということで、そういう状況を見ただけでも、何で品川区はこの時期に、経費削減というのを一つ掲げているけれども、指定管理者制度を導入するのか、そういう点でも私はよく理解できないので、あえてこの来年度導入していこうという、そこのところをもう一度よく教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"次にサービスの向上のところですが、現在でもサービスというのは特に喜ばれているところですが、今後開館日の拡大等、さらにレベルアップをさせたいと考えているものです。経費は、先ほどお答えしましたが３,０００万円程度のコスト削減になるかと考えているところです。","voiceIndex":59,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"そうなると、５年のスパンで指定管理者を受託される業者が、株式会社になるのか、ＮＰＯ法人になるか、あるいはどういうところがなるのかわからないですけれども、そういうところが、利益を大幅に出さないまでも少なくとも赤字は出さないで運営しなくてはいけないわけですから、そこに専門性のある職員を配置しながら、オープンを増やしていく、そうなると職員の一定の人数が当然必要になるわけですよね。","respondent":"中元品川図書館長","answer":"採算性というところをご心配のご質問ですが、採算性につきましてはきちんとこちらで、決して安い価格で計上するのではなくて、きちんと見積もった必要な金額を盛り込んだ上での予算措置をしていくということで、対応していきたいと考えています。","voiceIndex":61,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"わかるけれど、やはりこれを破綻させてはならないと思いますので、それが住民にとって一番最悪の状況になると思うので、そういった点でちょっと質問するんですけれども。今、現実的に品川区の図書館が１０館で頑張っている住民へのサービスというのは、単に貸し出しだけでなくて、どんなことがあるんでしょうか。レファレンスも含めてどういうサービスをしているのか、全て教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"レファレンスですが、品川図書館（中央館）におきまして統括をしていますが、地区館におきましては、既に地区館の委託事業者がレファレンスも対応しています。","voiceIndex":63,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"ですから、これはぜひ、少ない職員の中でやり続けていただいていると思うし、９館の地区館はほとんど正規職員はいなくて委託になってしまって、それでも一生懸命頑張っていただいていると。品川図書館に職員が何人いらっしゃるか定かにはわからないけれども、少なくとも減らしていった人数程度はいるんでしょうか。そういう図書館の職員の皆さんの仕事量というのは、相当大きなものがあると思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろな苦情対応とかそういうところも含めて、正規職員が応援に行っているから委託している事業者のところの水準が、住民サービスでも守られてきている、こういうことですから、これが全く正規職員の手が離れていった中でどうなのか、そういう心配があります。そこについてはどういうふうに検討してきたのか、またどういうふうにしようとしているかというところを聞きたいと。","respondent":"中元品川図書館長、田村教育次長","answer":"チーフやサブチーフなど、責任者クラスの配置を手厚くするというところで、今ですとわざわざ正規職員が出張するタイムラグができてしまいますが、今後は地区館できちんとそこでの対応を、サービスも含め、苦情対応も含め。そうすると事務で採っている人が、そこにずっと退職まで張りついているというわけでないので、やはり指定管理者にすれば一定の期間、４年なり５年なり、少なくとも専門のノウハウを生かした対応で区民サービスができるということで。","voiceIndex":67,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"そこを変えていくということを、なぜ検討しないのかというのが一つです。それを聞きたいです。そういうところ、公だからできてきているのに民間の方たちにそこまで採算を含めて課すなどということになったら、本当に大変なことになっていくと思うので、そのあたりの検討というのはどういうふうにしたのか、いくら聞いても出てこないので、改めてそこは伺っておきたい。この２点です。","respondent":"中元品川図書館長","answer":"実際、今、私ども地区図書館では、非常勤時代から同じ方がそのまま民間の会社に採用されて、継続して従事してくださっております。そのまま地域の方へのサービス向上に努めているところですので、継続性につきましても、実態として十分に継続できると思っているところです。","voiceIndex":70,"id":"exchange-021"},{"speaker":"南委員","kind":"意見","question":"そういう点で、専門性だとか資格というのは、地区館だからそんなに必要ないと、ちょっと乱暴な言い方ですけれど、そういう考え方には私は立ってほしくないと思うし、充実させてどんなサービスにも対応できる、そういうふうに努力してくださっていると思うんですけれど、そういうふうにあるべきだと思うので、とりわけ先ほどの答弁については、私は違うという意見を申し上げて、とりあえず終わります。","respondent":"田村教育次長","answer":"ちょっと勘違いしないでいただきたいんですけれど、司書の質問でされているので専門性と言っているだけであって、うちの職員は異動してきたと同時に、あるいは新規採用で採っても、ちゃんと研修だとかそういうものを充実させて。","voiceIndex":72,"id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう中で、ちょっとこの条例の新旧対照表のところで確認させていただきたいんですが。一つは第９条の個人情報のことで、私の不勉強かもしれないんですけれど、国のほうに個人情報保護法というのがあって、そこで一定の罰則なりそういうものがある中で、あえて条例に謳うのはなぜかというところがよくわからなかったので、教えてください。そこのところを確認したいと思います。","respondent":"中元品川図書館長","answer":"１点目の第９条の個人情報の取扱いですが、こちらは地方自治法の定めで、指定管理者を導入する際にはこれを条例の中にきちんと定めなさいというものに基づいて、盛り込ませていただいております。","voiceIndex":74,"id":"exchange-023"},{"speaker":"塚本委員","kind":"確認","question":"今の後半の修繕の件に関してですけれど、他区の例ということでしたけれど、品川区の他の指定管理者でもやはりそういう形が多いのではないかと思っているんですけれど、そこを一点確認したいのと。","respondent":"中元品川図書館長、田村教育次長","answer":"そういう意味で厳格に、特にデータとしてまとめて持っているところもありますので、そちらの部分について厳密な取り扱いをしなくてはいけないということで、盛り込まれていると考えております。そういうものについては、もちろん全部直せとか費用負担の問題は当然、業者のほうは飲み込みできない話ですから、後でまとめてお支払いするにしても、早急に対応しなければならないと。","voiceIndex":76,"id":"exchange-024"},{"speaker":"大倉委員","kind":"質問・要望","question":"指定管理者制度を導入する、しないにかかわらず、品川区は公のこの図書館の役割というものをどういうふうに捉えて考えているのか教えていただきたいのと、またその指定管理者制度を導入していく中で、どういった図書館像というか、どういう区民が利用しやすい図書館にしていきたいのかというのがあまり見えてこなかったので、こういうふうにしたいという思いというのを聞かせていただきたい。","respondent":"中元品川図書館長","answer":"２番目の区民が利用しやすい図書館への思いですが、こちらは今後、業務要求水準書のほうでもきちんと書かせていただきますが、先ほど申し上げた役割をきちんと果たしていきたい、それも地区館も含めて、きめ細かく地域へも対応していきたいという思いがあります。","voiceIndex":79,"id":"exchange-025"},{"speaker":"大倉委員","kind":"質問・要望","question":"役割と、こういう図書館にしていきたいというのはわかったんですが、今回こうやって時間延長のニーズが大きいとか、きめ細かいサービスをもっとしていくんだということで、指定管理者制度を導入することによって、この課題というのはしっかり解決できるという認識だと思うんですが、今まで高いサービスをより安くするというのに。","respondent":"中元品川図書館長、田村教育次長","answer":"現状、実際に地区館ごとに既にボランティアをここ何年も育成してきまして、ボランティア主体で子ども向けのおはなし会もやっていただいている状況ができてきておりますので、ボランティアも段々育ってまいりましたので。今回提案している指定管理者については、その部分も含めて、品川図書館は先の動向を見てからどうするか考えますけれど、地区館についてはそれなりに責任と権限を指定管理者の中で持たせて。","voiceIndex":81,"id":"exchange-026"},{"speaker":"大倉委員","kind":"質問","question":"ちょっと違う質問なんですが、先ほど特別区で１１区は導入が既にされていて、８区が２期目を迎えているという中で、他区の状況なのでわかるかどうかわからないですけれど、そういった導入をされている区は、協議会とかそういった会があって設置をされていると思うんですが、品川区ではどういう検討がなされたかというのは出てきていなくて、今度こういうのをやりますということになっているんですが。","respondent":"中元品川図書館長","answer":"そこはご意見を伺ったりする、図書館運営に関して住民の方と共同して前向きにいい図書館運営を行っていこうという、そういう協議体ですので、今回の件に関しましては品川区として責任を持って、内部で検討を進めてきておりますし。","voiceIndex":84,"id":"exchange-027"},{"speaker":"大倉委員","kind":"質問","question":"ではその内部で検討したという、どういう検討をされたかというのは、わからないですか。","respondent":"中元品川図書館長","answer":"そのようなご指摘を受けて、まず図書館内部で職員自らが私と検討会議を持って、さまざまな声を調査したり分析をしてきて、案をまとめてきたというものです。","voiceIndex":86,"id":"exchange-028"},{"speaker":"大倉委員","kind":"質問","question":"内部でさまざま検討してこういう結果になったということなんですが、例えば今後、平成２７年度には指定管理者による運営が開始される中で、そういった外部との検討委員会等、サービスが低下していないかとか、ちゃんとした運営・管理ができているのかとか、そういう外部の視点を入れて、図書館運営というのをしていくことも必要ではないかと思っているんですが、協議会の設置等に関して。","respondent":"中元品川図書館長","answer":"現状では、図書館協議会の設置という形では考えてございません。ただ指定管理者を入れる以上、今後モニタリングということで、評価をして議会にご報告をします。そちらのほうできちんと運営状況を確認、検証してまいりたいと思います。","voiceIndex":88,"id":"exchange-029"},{"speaker":"大倉委員","kind":"確認","question":"最後にちょっと細かいことなんですが、選書に関してさまざまなところで指摘があるかと思いますが、品川図書館が選定していくのかという確認と、指定管理者制度導入で運営が変わることによって、警備面とかさまざまな管理という部分は、どのように変わっていきますか。","respondent":"中元品川図書館長","answer":"警備のほうですが、現在警備員につきましては、総務課予算で配置をしています。こちらはまた、今後総務課と協議いたしまして、どういう形になるか検討してまいりたいと思っているところです。","voiceIndex":90,"id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"反対です。反対の理由は、５年という期間での運営をすることになるわけですから、運営そのものが長期的視野に立てないという問題点。そして利用者が増えるほど運営上の負担が増える、こういうことになるわけですから、指定管理者制度にはなじまないという点が二つ目。反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-031"}]},{"id":"topic-04","title":"平成２６年請願第１号 待機児解消にむけ、区立認可保育園の増設を求める請願","agenda":"平成２６年請願第１号 待機児解消にむけ、区立認可保育園の増設を求める請願","exchanges":[{"speaker":"南委員","kind":"質問","question":"改めて今年の入園者数、そして不承諾通知を出した数、その不承諾の中での地域的にはどういう状況だったかということを、まず伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに入園審査の状況です。第１回定例本会議のほうでもご答弁申し上げましたが、第一次審査時点で認可保育園の入園申込者数は２,５３２です。そのうち内定をこちらのほうでさせていただきましたのが１,６３８ですので、不承諾者数は８９４件になります。","voiceIndex":105,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"そういう体験を持っているだけに、今、この請願に８７０人余の方たちが署名をして、品川区議会に提出されたという気持ちは、本当に一人ひとりの皆さんの気持ち、熱く重く受けとめていきたいと思っているんですけれど、そういうことに対して区立認可保育園を１園で、これでいいというふうに考えているのか、そのあたりの見解も伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"この対策は引き続き、来年度以降もとってまいります。区立保育園の開設につきましては、幼保一体施設の整備の中でこれまで行ってきておりますので、この計画を今変える予定はございません。","voiceIndex":107,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"その辺をまず伺いたいと思うんです。そういうところも含めて改めて紹介をしたいと思いますので、そういう土地があるわけですから、ぜひこういう８７０人余のお母さんたち、苦しい選択をこれからしなくてはいけない、そういう状況に追い込まれているお母さんたちの思いを受けとめて、どういうふうに品川区としてこの願いに応えていこうとしているのか、そこについて決意をもう一度伺いたいと思うんです。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後国または東京都から、保育施設も含めてそういうふうな都有地、国有地の提案があった場合には、改めてその時点での保育事業またはほかの施設も含めての検討を、区として総合的にして進めてまいります。","voiceIndex":109,"id":"exchange-034"},{"speaker":"南委員","kind":"提案","question":"「提案全てを実行したとしたら、６００億円の基金もすぐに枯れ果ててしまい、やがて赤字財政にならざるを得ない」、こういう答弁をしたんですよ。６００億円の基金を全部保育園に使ったとしたら、何園分できるんですか。区長が本会議でこういうふうに答弁されたんですから、ぜひ１園の建設費はわかるでしょうから、それで大体はじくと６００億円は何園分かという、一定の数は出てくると思うんです。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに保育の実施のことですけれども、現在設置主体として多様な主体が認められていること、また区立というふうにおっしゃいますけれども、全て児童福祉施設の設備および運営に関する基準や通知などで、最低基準等が決まっております。","voiceIndex":111,"id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"建設費もぜひ教えてください。数年前の私たちの調査では、１園の建設費に２億６,０００万円というふうにはじき出したんですが、それでいいのかどうか。運営費は９０人で１億５,０００万円、これは１年間の経費というふうに私は聞いたのですが、そういうことでいいんでしょうか。私立保育園で聞いたわけではないので、公立保育園の１園の建設費は幾らなのか、これを教えてください。","respondent":"金子子ども未来事業部長","answer":"この問題に関しましては、何回も本会議あるいはこの委員会でご答弁してきたとおり、品川区としましては、認可保育園、区立、私立、認証保育所、保育ママ、あくまでも積極的に総合的に取り組んでいくということを何回もお話ししているとおり、この考え方については現在そうですし。","voiceIndex":113,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"そこはしっかり受けとめるべきです。それで保育園に子どもを預けている方は、所得税に見合って保育料だって払っているじゃないですか。教育もそうですけれど。そういうところに財政効率を優先させていいでしょうか。必要な経費を払っているじゃないですか、保護者としての保育料。その上に、さらに財政効率を課すんですか。必要なお金。そういうふうに思いますけれど、その点はどうでしょうか。","respondent":"金子子ども未来事業部長","answer":"そういう意味で、財政効率を優先させているではないかというご批判は全く当たらないと思います。待機児童対策を積極的に進める中で、当然のことながら財政効率も考えている、これは我々行政をつかさどっている者の責務だと考えています。","voiceIndex":115,"id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"私は違うと思っています。それで、株式会社は全部で２０何カ所ですか、株式会社立の保育園が何園か、ちょっと改めて聞きたいと思っていますが、この間の本会議の答弁では１７園が園庭がないというふうに答弁されましたよね。それは株式会社の保育園のところで、１７園が園庭がないというふうに私は理解しているんですけれど、何園中１７園なんですか。ここもちょっと伺っておきたいと思います。","respondent":"金子子ども未来事業部長、今井制度改革・待機児童対策担当課長","answer":"私の所管でいえば、社会的なニーズが非常に高まっている現在の待機児童対策については、積極的に、手法としては総合的にですけれども、姿勢としては積極的に取り組んでいるということを何度もご答弁申し上げておりますので。そのときに平成２６年４月１日現在でという前提がついていたかと思います。現在は私立保育園は２４園ですけれども、今度平成２６年４月１日に４園開設いたしますので、私立保育園としましては全部で２８園になってまいります。","voiceIndex":117,"id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"そういう中で、これからも来年度は４園できるんですけれども、多分園庭はないと思います。子どもの保育にとって、園庭は必要ではないかと私は思うんですけれども、園庭の位置づけについての見解、必要ではないというふうに品川区は考えているのか。代替施設があるということは別にして、保育園の園舎に接続した園庭があることが望ましいと私は思うんですけれど、そのあたりの見解はどうでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに株式会社立でも、今、委員ご指摘のとおり２園、屋外遊戯場を自園のところで持っているところがあります。","voiceIndex":120,"id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"必置は求めていないということなんですが、大都市の中の環境等々はもう致し方のない状況はあるんですけれども、しかしだからといって、近くの公園とか、境内とか、そういうところで代替が確保できればいいということでよしとしないで、できるだけ自治体としてはちゃんと追求していただきたいと思うんですね。そういうふうに私は思うわけです。こういうところの見解はどうなんでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こういった中では、屋外遊戯場のあるなしにかかわらず、その屋外遊戯場や代替地で果たされる子どもの成長の発達の支え、どういうものを教育、保育していくのか、ここの部分について、さらにどういうふうにやっていくかということを検討していく必要があると考えております。","voiceIndex":122,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"先ほど質問したけれど答弁がなかったことがあるので、改めて伺いたいんですが、保育園の建設費は幾らなんでしょうか。この１億５,０００万円という数字そのものを聞いたら、確かにそれなりの金額だなと思いますけれども、将来の子育て、教育費としてみたとき、品川区としては多いというふうに思っているでしょうか。その辺りの認識も改めて伺いたいと思います。幾つかの質問、答えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区の社会福祉法人また株式会社等、施設整備費については、区の独自の積み上げを含めて８分の７までの補助を出しております。ただ対象外経費もありますので、各法人がどのぐらいどんな施設をつくっていくかというのは、それぞれの園の考え方によって変わってまいります。","voiceIndex":124,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"私立保育園の建設費ということで答弁していただいているようなので、私は区立の保育園の１園当たりの建設費、これが幾らなのかということを質問したつもりなので、先ほどの聞き方がもし悪かったのであれば、そういうことで答弁をしていただきたいと思います。","respondent":"金子子ども未来事業部長","answer":"ただ長い間デフレの時代で、一定のコストというのはそんなに変わっていないと思いますので、昔から言われているのは、１００人定員で大雑把に申し上げて２億円の建設費がかかるというふうに言われております。ですが、最近の細かい動向についてはちょっと掌握しておりません。","voiceIndex":126,"id":"exchange-042"},{"speaker":"本多委員","kind":"質問・要望","question":"この不承諾の方たちへの対策で認可保育園を増設、つくっていくとなると、もっともっと時間がかかるということは、これまでの文教委員会の議論でもう既にわかっていることですので、今品川区が進めている手法を推し進めていただきたいのとあわせまして、認可保育園に入れなかった人たちのせっぱ詰まった声というのは、認証でも保育ママ制度でも入りたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-043"},{"speaker":"本多委員","kind":"質問・要望","question":"ただいま申し上げたとおり、結論を出していただきたいと思います。態度は不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-044"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すことでお願いします。態度については不採択でお願いします。遊びとか園庭というところでいえば、子どもたちは遊ぶことが大切だと思いますので、質の向上は大事にしてほしいと思ってはおりますが、さまざまな取り組みの中で待機児童を少しでも減らしていこうというところでやっておりますので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-045"},{"speaker":"高橋委員","kind":"質問・要望","question":"きょう結論を出すということで。今、お話がありましたが、区立保育園を含めて多様な形で施策を進めているということなので、さらに積極的に進めていただいていると認識しています。ただ、待機児童がゼロにならないところがあるので、さらに今の状態で進めていただきたいと。という状況で、現状の対策が行われていると思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"私どもの試算でも、数年前ですけれど２億６,０００万円程度だったということで、品川区の財政状況から見て、十分にこれは対応できることなんですね。もう諸外国では１クラスの人数なんて２０人、それ以下のところが圧倒的じゃないですか。そのためにもここに８７０人もの方々の名前を連ねて提出された、区立認可保育園を増設してくださいという、これを真摯に受けとめるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4816#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":45975,"voices":142}},{"id":"h26-20140224-5","meetingId":"h26-cm02","date":"2014年2月24日","dateIso":"2014-02-24","committee":"総務委員会","time":"午前１０時００分～午前１１時３３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この審議会のことで、基本的なところをちょっと教えていただきたいんですが、特別職報酬等審議会というのが、これは区長と議員の報酬や給料について審議するということなんですが、教育委員とか選挙管理委員会とか監査委員などの報酬などについての審議するという委員会というのはないのかというところが１点なんですけ。","respondent":"工藤総務課長","answer":"区議会議員におかれましては８年ぶり、品川区長および副区長、教育長につきまして４年ぶりですけれど、特別職報酬等審議会の中では毎年意見を聞くものという形になってございまして、考え方ですと、毎年必ず意見は、１回開いているですけれど、そのさまざまな状況等によって。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのメンバーの１５人なんですけど、公共的団体の代表者や学識経験者ということですが、具体的に公共的団体というのはどんなところなのかということを、ひとつ教えていただきたいのと、適正な額の基準の考え方というのは、こうある一定決まっているものを今回みたいに引き下げるとか、また引き上げるとかというふうなところでは、それぞれの今までの区の職員との関係ですとか、他区の関係という。","respondent":"工藤総務課長","answer":"この改定の率の差を累積いたしまして、その累積がおおむね１.０％前後ぐらいになったときに改定をしているという部分が、１つの物差しになろうかと。そういう形でやってきた経過等もございまして、そのような形で考えているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところを、それぞれにちょっとあったら教えていただきたいということです。","respondent":"中山総務部長","answer":"そもそもの特別職の報酬、給与等の考え方というのはそれぞれですが、職責、地位、役割、そういうことを総合的に勘案して、それぞれ条例でご議決をいただいて決めているですので、それに対する答申を踏まえての改定の考え方は総務課長が申し上げたとおりですけれども。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"まあ、そういうあれだと思いますけれど、わかりました。今回、区議会議員、教育委員会、選挙管理委員会、監査委員という形での、この改定なんですが、それぞれ年額で幾らぐらい削減ができるのか。その額を教えていただけたらと思います。","respondent":"工藤総務課長","answer":"いろいろと給料月額、職によりまして若干異なっておりますけれど、大きな部分でお答えしますと、大体年額で１０万から１５万ぐらいの減額になろうというふうに考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ありがとうございました。区議会で３３０万円ということですが、教育委員会、選挙管理委員会、監査委員とかというふうなのは総額でどれぐらいになるかというのが計算されていないという、そこら辺はちょっと、ぜひわかる形で報告をしていただけたらなと要望をさせていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"このたび、東京都人事委員会のほうから、民間の給料が大きく下がっているということで、品川区の特別職報酬等審議会の答申で、前年度の民間給与が下がった分をこちらのほうにも当てはめてきているということで、それはわかりますが、６ページにも書いてあるとおり、ちょうど終わりの中段あたりで、現在の厳しい社会経済情勢や区民感情等に配慮するとともに、区民および職員と痛みを分かち合うという観点から。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっとお伺いしますけれども、これは今まさに特別職報酬等審議会という位置づけをもう一度改めて伺いたい。","respondent":"中山総務部長","answer":"説明、言い方が若干不十分だったことはあったかもしれません。過去のいろいろな改定の答申をする。","voiceIndex":18,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１点ちょっとお伺いしたい。私もこれは不勉強だったんだけど、これ、毎年、先ほど年に１回開かれているとおっしゃってたんだけど、これ、諮問がないときも年に１回開かれて、そのときは何らかのこれが適正だとか、まあ、わからないんだけど、それを見たことがあまりないんだけれども、必ず何か報告書というのがあったんでしょうか。すみません、ちょっとよくわからないので、そこら辺を。","respondent":"工藤総務課長","answer":"毎年１回開かれているということでございまして、当然その審議会の中では２３区の状況等は必ず出して、そういった部分でご議論はいただいているところです。勉強会という形でご議論をやっていただいているです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"それでもなければ、何らかの形で２３区は今こういう状況だからという諮問を受けなきゃやらないわけだとするならば、その普通のときの位置づけというのは、まるっきり勉強会なんですよとか、意見交換会なんですよとか、そのふだんのときの位置づけというのはどういうふうになっているのかだけ教えてください。","respondent":"中山総務部長","answer":"特別職報酬等審議会、特に条例に定める中で、第２条の中で、毎年１回、審議会で意見を聞くというふうになっておりまして、それは改定の諮問等がない場合については、状況についての勉強する場という形ですが、あくまでもこの条例に基づいた審議会ですので、諮問。","voiceIndex":22,"id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"多くの区においても、これから審議会ということで、品川区が行い、また、ほかの区も行っていくんでしょうけれども、その中で、過去においてでもいいんですけれども、例えば判断が異なったと言うんでしょうか、下げたところもあるし、上げたところもあるというのでしょうかね。そういうようなことは過去にあったのかどうかということについて教えてください。","respondent":"工藤総務課長","answer":"２点目ですけれど、２３区のいろいろとばらつきですけれど、基本的には２３区、人勧の部分を尊重しているという部分ですので、特別区人事委員会勧告の改定率に沿ったような形で動いているというのが現状です。","voiceIndex":24,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"そうしますと、人事委員会勧告のほうに逆らってとは言いませんけれども、異を唱えて下げるところを上げるとか、２３区でそういうばらつきと言うんでしょうかね、そういうものは過去にあったのかどうか。この点、もしおわかりになれば教えてください。","respondent":"中山総務部長","answer":"過去となりますと、いわゆる増改定の時期等もありますので、全てを把握しているわけではございませんけれども、基本的には総務課長も答弁申し上げたように、一般職員の改定を踏まえながら、総合的に各区においても審議会でご議論いただいてやっているところで。","voiceIndex":26,"id":"exchange-011"}]},{"id":"topic-02","title":"第１４号議案、品川区職員定数条例の一部を改正する条例","agenda":"第１４号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"時代背景で昭和５８年とか、その辺はどういう時代背景だったかわからないですが、明らかに減っている中で、何でここまで減らしてきたのか、時代背景も含めて、その理由と、今後、本当に大きな話になっちゃうんですけど、品川区自体が何人の職員だったら十分やっていけるというふうにお考えなのか。","respondent":"堀越人事課長","answer":"ただ、やはりいろいろな課題等もありますので、そういう部分は必要なところにしっかりと対応できるように、効率化が図れるところは効率化を図って、そんな形で職員の数については適正な管理をしていきたいというふうに思っているところです。","voiceIndex":44,"id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今後もそういった部分があると思いますので、区長もおっしゃっていますように、『小さな区役所から大きなサービス』という部分で、人数を減らしたことによってサービスが低下してしまうということは絶対あってはいけないことで、逆に増やしたことによって、いいサービスが提供できるかというのはまた別な話だと思いますので、しっかりとサービスはよくしていきながらも、スリム化と言うんですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと説明でよくわからないところがあったので教えていただきたいんでが、付則の７０名というのは、７０名の内訳というのがどういう中身になっているのかを、ひとつ聞かせていただきたいと思います。","respondent":"堀越人事課長","answer":"付則の内容ですけれども、先ほども答弁させていただいたとおり、区の職員の定数としては、この２,４８０名というのが現時点であるべき姿だというふうに考えているところですが、一方で、現在、待機児対策等を進めていまして、保育士を多く採用しているところでございまして。","voiceIndex":47,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"じゃあ、保育士はその待機児対策ということで、７０名までは定数を超えても採用して、その対策に充てるよということで理解していいんでしょうか。それが１つと。そして、その休職、育児休業、公務災害休業、結核休業から復職した職員の１年限りの定数外という方は、それぞれどれぐらいいらっしゃるのかということをちょっと教えていただきたい。","respondent":"堀越人事課長","answer":"同じ定数外という言い方をしていますけれども、こちらで言っている保育士の７０名につきまして、稼働人員ですので、実際の職員定数のあるべき姿、基準としての２,４８０名ですけれども、稼働人員である保育士の７０名の部分については。","voiceIndex":49,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"具体的なところの減になるところでお聞きしたいんですが、児童指導のところで、児童センター、２ということで、業務委託館で退職による２名減ということなんですけど、今、業務委託をされている児童センターというのは、どれぐらいあるのかということ。それから、業務委託されているところで、職員なり、再任用なりで配置されているところはどれぐらいあるのかということを教えていただきたいと思います。","respondent":"堀越人事課長","answer":"児童センターですけれども、今２５館のうちの１２館について業務の委託をしています。それから、再任用が配置されている館はそれぞれのところでありますけれども、ちょっと済みません、今、手元にございません。委託している館には職員の配置は基本的にはございません。","voiceIndex":51,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この児童センターの委託館というのは、去年の議事録をちょっと読んだら、６館と書いてあったんですけど、１年間にさらに２倍に委託館が広がったという、そういうふうなことなんでしょうか。そして、そこのところから、また職員を削減していくという、そういう考え方になっていくのか。そこら辺のところの児童館の委託の方向とあわせて、職員の定数のところをお聞かせいただきたいと思います。","respondent":"堀越人事課長","answer":"今後の仕組みですけれども、委託も入れていろいろ効率的な執行を図っていくというのが基本的な考え方です。今すぐ何かという話は所管からも聞いてございませんけれども、いろいろな観点を入れながら、効率的な執行体制に努めていくというのが基本的な考え方です。","voiceIndex":53,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところもお聞かせいただきたいと思います。先ほどの説明でちょっとわからなかったのが、建築課の執行体制の見直しで１名減になるというあたりの理由がよくわからなかったので、もうちょっと詳しく教えてください。","respondent":"堀越人事課長","answer":"委託館に職員が必要がどうかですが、委託をして、その事業者のほうに業務をやってもらうということで、全体として職員を配置する館ですとか、所管の子育て支援課のほうで業務が適正に行えるかどうかは十分把握をしておりますので。","voiceIndex":55,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この一番最後のページを見ると、毎年毎年ずーっと減らされて、直営が委託になりというふうな形で職員が置きかわっているというふうな状況になって、昭和５８年からですと、プレス発表を見ると、１,８１７人減らされて削減をしてきたということが書かれているわけですけれども、１,８１７人減らされたかわりに、やっぱり区役所の業務というのはあるわけですから、そのかわりに委託の職員であったりとか。","respondent":"堀越人事課長","answer":"業務委託につきましてが６００名程度というようなところで、そのほかは事業の縮小等などによるものが、本当に主な形になりますけれども、主な内訳となるものです。","voiceIndex":57,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところで働いている人の総人数というのはわかるんでしょうか。そこら辺のところが６００名ということではないのではないかなと思うんですけど、そこら辺の例えば、給食にしてもそうですし、すまいるスクールとか図書館業務ですとか、いろいろと委託のところがこの間、ずーっと増えてきたわけですけど、そこで働く総人数というふうなあたりもわかればちょっと教えてください。","respondent":"堀越人事課長","answer":"済みません、私のほうでちょっと説明があれだったんですけども、今、全体の中のおよそ１,８００名という職員を減してきたうちの約１,０００名減した分については職員配置の見直し等いろいろ工夫により職員数を約１,０００名ほど減したということで。","voiceIndex":59,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと改めてもう一つお聞かせいただきたいのは、今回、ずーっとこういう形で削減、削減ということで来ているんですけども、私たち、ちょっと遅くまで仕事をしていたときに、かなり１０時、１１時、１０時ぐらいのところではもう本当にたくさん仕事をされている方が多くて、１１時過ぎても仕事をされている方というのも結構あるんですけれども、そういうふうなところで、所管から人が足りなくて。","respondent":"堀越人事課長","answer":"ただ、先ほど待機児対策で保育士の部分についてお話しさせていただきましたけれども、必要なところには職員を充てて事業執行を行う。一方で、工夫できるところは工夫していくというのが基本的な考え方です。","voiceIndex":61,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"各所管から要望事項というようなことなんですけれども、そこの中で、定員を増やしてほしいという要望はなかったのか。それにもかかわらず、それが増えないというふうなのがなぜなのか。それとあとは、組合からもそういう定員を増やしてほしいという要望はないのか。そこら辺のところをお聞かせいただきたいと思います。","respondent":"堀越人事課長","answer":"組合のほうは一定の考え方を持っているとは思いますけれども、私どもといたしましては、組合に対しても説明して、区としての考え方を示しているというものです。","voiceIndex":63,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ずーっとこの定数条例を見ると、やっぱり削減に次ぐ削減という感じがして、そして、職員の状況を見ても、本当に一時的な繁忙等で残業しているというよりは、何か恒常的な残業というような感じが状況を見るとどうしてもするんですよね。そういうふうなところで、やっぱり必要なところにはきちんと配置していく。保健師さんなどもすごく足りないというふうな話も聞くんですけど、そこら辺のところと。","respondent":"中山総務部長","answer":"個別の事情については個別の対応を図っていくですので、ご理解をいただきたいと思います。","voiceIndex":65,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それともう一つは、やっぱり職員を、定数を削減して委託に切りかえて、それこそ先ほど言われました年収３００万円以下のワーキングプアを、官製ワーキングプアというふうに言われてますけど、そういう状況を大きく増やしていくというやり方はやっぱり考え直していくべきではないかなというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"大したものだなと思います。ところで１つお聞きしたいんですが、今やはりどんどん社会情勢の変化、そして、それによって区民の働く勤務形態もどんどん変化していると思います。それとも、あくまでこの今の職員の勤務状態、区民に対するサービス体制、時間帯ですか、曜日も含めてなんですが、どのようにお考えなのか、ちょっとお聞かせください。","respondent":"堀越人事課長","answer":"いろいろ全体の職員の配置体制の中で工夫をしながら対応をしているというものですので、そういったさまざまな状況を見ながら、情報を取りながら、対応しなくてはいけないところには工夫を図りつつ対応するというのが基本的な考え方かと思います。","voiceIndex":68,"id":"exchange-025"},{"speaker":"浅野委員","kind":"質問","question":"付則の７０名というところでちょっと参考までに教えていただければと思うんですが、７０名を限度として定数外とするということなんですけれども、この４ページの一覧表を見ますと、その付則自体で、例えば平成９年から平成１５年までは８１とか９２とかすごい、何と言うんでしょうかね、下１桁まで出てて、それ以降については７０、５０云々という数字になっていますけど。","respondent":"堀越人事課長","answer":"今回の場合ですと、保育士の採用につきましては、若い職員も増えておりますので、そういった部分に対応しまして、育児休業の代替職員として任期付の採用等の見込み等がございまして、その部分につきまして、一定程度の安心分と言いましょうか、安全弁と申しましょうか。","voiceIndex":70,"id":"exchange-026"},{"speaker":"浅野委員","kind":"質問","question":"時代背景で随分と変わってきているなというところがあるかと思いますので、あとちょっと、先ほど１つ質問しました、この付則の考え方というのは基本的にはこれは変わっていないのか。それとも何かしら時代背景で変わる部分があるのか教えてください。","respondent":"堀越人事課長","answer":"基本的な職員数のあるべき姿というのをこの定数条例で定めておりまして、その中で職員の減にあたって、いろいろな状況の中で実際に減をしたところが実人員をオーバーするような可能性がある場合がありますので、付則を設けさせていただいているという。","voiceIndex":72,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけお伺いします。プレス発表でも区長はやっている。そうすると、ここら辺のところで、そういう部分で打ち出しますとか、例えば付則でもいいんだけど、何かせっかくこういう今のずっとこう議論を聞いていると、その政策的なものを打ち出す１つ増の要因みたいなところを付則も含めて、そういう考え方を出す、出しやすいところだと思うんだけど、そこら辺の考え方というのは教えてもらえればなと思います。","respondent":"堀越人事課長","answer":"ですから、政策は政策として区としては打っていくというところで、そこで職員の増と連動するところとそうでないところがあるということで、何か政策についてそういう方向、何か特別な理由があるというわけではなくて政策は政策で進めていくという考え方です。","voiceIndex":74,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"反対です。職員がやりがいを持って働ける、また身体、精神の健康を守れる労働条件を保障するケースにしていただきたいと思います。そして、また、全て委託、委託ということで委託に任せるのではなくて、区民の実態を把握して政策に反映させるという点からも、委託のところにも職員をきちんと配置をするという、そういうところでやっていただきたいと思いますので、この条例には反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-029"}]},{"id":"topic-03","title":"第２９号議案、専決処分の承認を求めること","agenda":"第２９号議案、専決処分の承認を求めること","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"今回、時間がない中、大変な作業で乗り切られたということですけれども、報道によりますと、品川区のほうで少し開票の結果がおくれたというのも挙がっております。要因はさまざまだと思いますけど、その概要を教えていただきたいのと、それによって何と言うんでしょうか、余計に費用がかかったと思うんですね。その部分の概要がもしわかれば教えていただければと思います。","respondent":"諸岡選挙管理委員会事務局長","answer":"簡単に申し上げますと、不在者投票者数を若干、東京都への報告後、判明いたしまして、それを修正したというものです。それによりまして、最終的な投票、開票結果の提出がおくれた。約１時間ちょっとおくれたですが、経費的な面での負担というものは特にございませんでした。","voiceIndex":88,"id":"exchange-030"},{"speaker":"浅野委員","kind":"質問","question":"これ、ここにあったのでお伺いしたんですけれども、いろいろ開票を早くするための努力もされていると思います。機械読み取りですから、こちらのほうも入れて努力されていると思いますけれども、やはりなかなか最後は大変な作業になると思います。これからも選挙というものは毎年のように行われるようですので、さらなる短時間でできるような取り組みというものはぜひとも進めていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回の都知事選挙、本当に突然で職員の皆さん、お疲れさまでしたと思います。それで、今回は雪の影響もあって、投票率がかなり下がったと思うんですけど、ああいう天候の状況がある中での投票率を上げていく取り組みというのが、どんなことがされたのかというあたりをちょっと教えてください。","respondent":"諸岡選挙管理委員会事務局長","answer":"当日の朝におきましても、投票用紙を選挙管理委員会の倉庫から各４３の投票所に配送する車が立ち往生するようなことがあった場合、かなり雪が深かったということで、一方通行のところでは、前の自動車がとまって一歩も動けなくなったというような事態もありましたので。","voiceIndex":91,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、お話をお伺いしただけでも、本当に大変な中ご苦労いただいたなというふうな思いがしているんですけど、雪のために行けないというところとか何かもあったと思うんですけど、そういう中での投票率を上げる啓発みたいなのは特別された部分とかというのは。ああいうふうな啓発がどういうふうな形でされたのかということだけちょっと教えてください。","respondent":"諸岡選挙管理委員会事務局長","answer":"は通常の防災行政無線でありますとか、懸垂幕とかそういったことはやっておりましたけど、今回、雪への対応で精いっぱいでございまして、その際の雪に対する特別な啓発ということは、ちょっと時間的にも余裕がなかったということが事実です。","voiceIndex":93,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":28709,"voices":106}},{"id":"h26-20140225-6","meetingId":"h26-cm02","date":"2014年2月25日","dateIso":"2014-02-25","committee":"区民委員会","time":"午前１０時００分～午前１１時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の山北町との水と緑のふれあい交流における「ひだまりの里」の運営","agenda":"の山北町との水と緑のふれあい交流における「ひだまりの里」の運営","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"山北町との交流なのですが、今回のこの資料にも書いてあるとおりで、向こうに品川区民の方が行かれて交流をするというのが基本的な事業だと思うのですが、逆に向こう側からこちらに来て、何かふれあいの交流というのがあるのかどうか、そこだけ教えていただきたいと思います。","respondent":"久保田地域活動課長","answer":"主には、向こうのイベントとかに八潮太鼓だとか大井権現太鼓の方が行って、そういった伝統芸能を披露して交流を行っているといったところが中心です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（し）委員","kind":"意見","question":"今後、この５年間にいろいろと交流のやり方等も検討するというようなお話をいただいていますので、ぜひその中で、山北町の方たちがこちらへ来て、またふれあい交流ができる、双方で交流ができればいいと思いますので、その点も含めてご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"正直詳しくなくて、わからないので教えていただきたいのですけれども、今の話ですと、いろいろ協議をしてきて、最終的にはいつも１０年だったのが５年間になって、今後交流のあり方を検討するということですけれども、要するに、今、どういう問題というのが起きているのか、協議の内容ですけれども、山北町がどんな主張があって、品川区はどんな主張があって、協議の中でどうなったのか。","respondent":"久保田地域活動課長","answer":"すみません、説明が足りませんでした。私どもが課題として持っているのは、この山北町との交流に当たりまして、品川区がこういった負担金を全額負担しているということがまず１点、大きな問題だと思ってあります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"経過のご説明がわかりました。だからそれはそうなのだけれども、ただ、そのあり方について検討しているということなのでしょうけれども、今後、このひだまりの里については、区としてはどういうふうに区民への提供というか、事業の提供といいますか、事業としてはどのように捉えていらっしゃるのか、先の展望も含めて考えをご説明いただきたいと思います。","respondent":"久保田地域活動課長","answer":"ひだまりの里以外でも山北町にはいろいろな観光資源等もありますし、自然もたくさんありますから、そういったところを向こうのほうとも話をしながら、活用しながら、多くの方が双方にとってメリットになるような交流ができればと思ってありますので。","voiceIndex":10,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先方との交渉、山北町の予算もあると思うので、その中でこれだけの金額の負担金を減額して、管理運営費も半分ずつにしたという、大変ご苦労だったと思います。お疲れさまでした。ちょっと聞きそこなったのですけれども、一番下の土地賃貸借契約期間、これは５年間になっていますけれども、この５年間、そっくり土地利用はm2当たり１７７円ということにしたのでしょうか。そこだけちょっと確認をしたい。","respondent":"久保田地域活動課長","answer":"すみません。説明が足りませんでした。","voiceIndex":12,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"金額の件はわかりました。これからもご努力をお願いしたいと思っています。さっき農園の関係も、どうしても一定の決まった人が使っていらっしゃるというのは、私どもが行ったときにも感じていますので、かといって無理に品川区民の方に行ってくださいという無理やりな形もまずいと思います。わかりやすく交流をしていただければと、その辺もこれからご努力をまたお願いしたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"山元委員","kind":"質問","question":"けれども、これの状況を見ると、結構山北町の方たちが使っていらっしゃるということで、もうちょっとこれ、品川区のメンバーが使えないというのは、例えば品川区は結構大学もありますので、ここに泊まりながらテニスをするクラブの人たちが使えたら、もっと利用ができるのかという気がするのですが、こういう施設に関しては、品川区というのは口出しができるというか。","respondent":"久保田地域活動課長","answer":"ひだまりの里については、品川区の山田副区長、中川原部長、私が運営協会の理事、メンバーに入ってありますので、年に数回、３回から４回ぐらいそういった協会の中でいろいろ意見交換をしていますので、意見を言うことは当然できますので、その分お金も、今。","voiceIndex":15,"id":"exchange-007"},{"speaker":"山元委員","kind":"質問・要望","question":"山北の駅というのは素朴な感じの駅なのだけれども、あそこら辺から迎えに来てくれるのか。でもとても夢のある、私は好きな駅でしたけれども、何かそういう少しでも行けるようなことを品川区でもしてあげると、もっと利用ができて、こんなにいいところがあるのかと思ってもらえるのではないかと思うのですが、その辺はいかがでしょうか。","respondent":"久保田地域活動課長","answer":"神縄トンネルバス停というところが一番の最寄りのバス停になると思いますけれども、ただ、そんなに本数があるというわけではありませんので、行くのは大変だと思いますが、電車で行くという方も当然いらっしゃいますので、あと丹沢の登山などで有名ですから。","voiceIndex":17,"id":"exchange-008"},{"speaker":"山元委員","kind":"質問・要望","question":"本当に、ぜひ皆様も１回行ってみると、こんなにいいところだったというのをちょっと思いましたので、泊まれるところも、細かいことですけれども天井を見ると結構しみがあったりとかして、もし若い女性が行くのだとすれば、そんなところをきれいにしてあげたらもっと利用ができるかと思いますので、細かい点ですけれども、やはりどうやったら利用できるかを考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"山北町なのですけれども、私は委員会の資料とかをいただいた段階で、あの利用率等を考えて、区としては次の契約をしていくのに消極的なのかという思いがあったのですけれども、継続していくという形になったわけですけれども、その協議の中に、品川区として継続していくのだという形の一番のポイントは何だったのでしょうか。","respondent":"久保田地域活動課長","answer":"そうした中で、山北町と協議を続けていく中で、品川区が、今、全額負担をしているといったところが課題だということがまず１点ございまして、それとあとは、やはり品川区民にとっての、一部の方ではありますけれども、多くの方が貸し農園を使ったり。","voiceIndex":20,"id":"exchange-010"}]},{"id":"topic-02","title":"のオリンピック・パラリンピック開催周知事業「日本トップアスリート体験ツアー」","agenda":"のオリンピック・パラリンピック開催周知事業「日本トップアスリート体験ツアー」","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"私も小学校高学年のときでしょうか、サッカーのラモス選手に会って、練習を受けるというよりもすごいということしか覚えていなかったのですけれども、やはりすごくどきどきわくわく、頑張ろうといろいろな思いを思うのですよね。今後についても伺いたいと思います。それと、経費というか財源ですけれども、これは全部一般財源ですか。東京都なのですか、国なのですか。内訳を教えていただきたいと思います。","respondent":"安藤オリンピック・パラリンピック推進担当課長","answer":"それで、子どもたちは口々に、ぜひ自分も２０２０年を目指したいだとか、そういう本当の気持ちになったです。それから、今後の展開ですけれども、「もう」と申しましょうか、「しかない」と申しましょうか、２０２０年まで６年と少しですね。","voiceIndex":27,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"もうちょっと、６年後に１６歳から１８歳、小学校高学年の方はいっぱいいらっしゃるわけですから、もっと人数的に多くしたほうがいいのではないかという思いなのですけれども。相手先もありますし、普通考えれば小学校単位で行くとか、ほとんどの行きたいという方には全て参加させてあげるような事業を考えると思うのですけれども、それでも次が各１４名程度ではないですか。","respondent":"安藤オリンピック・パラリンピック推進担当課長","answer":"非常に狭き門で、なおかつ引率を入れて１５名に限るという非常に厳しいものでございました。そんな中で、今回はこの形で１４名という形にさせていただいたところです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"人数的にということはよくわかりました。特にお子さんですから、なるべく知恵をまた出していただいて、一人でも多くの子どもたちがトップアスリート等に会える、指導していただくという事業を展開していただいて、２０２０年のオリンピックを大成功に終わらせていただきたいと思うのですけれども、改めて何かあればここでいただきたい。","respondent":"安藤オリンピック・パラリンピック推進担当課長","answer":"２０２０年のオリンピック目指して、区として私どもができることはやっていきたいと思っています。そして区長が申しますように、子どもたちの夢のバトンタッチというものを我々は真剣に受けて、事業を展開していきたいと考えています。","voiceIndex":31,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"教育上なのですが、この見学について下調べをして、そして感想でまとめるというのは大切だと思うのです。そういうので、行ったお子さんたちの例えば形ある影響とか、行かないお子さんたちに対する周知の意味もまたあって、行ったときの報告とか、そういうのがあるのでしょうか。","respondent":"安藤オリンピック・パラリンピック推進担当課長","answer":"今回について、行った感想というものは一応もらっています。それをもらって、我々の企画者、我々職員が次への反省材料としてそれはやっているところです。それを行かなかった子どもたちに対して周知するとか、そういうことは、今は考えてはございません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"これというのはいい機会ですね。学校でも例えば行った人たちの発表の会とかがあったら、これは要望なのですけれども、これからこういう機会がたくさん増えるのも希望だというので、そういう報告があったらいいと思うので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"}]},{"id":"topic-03","title":"の２０１４、ウーマンズビジネスプランコンテスト","agenda":"の２０１４、ウーマンズビジネスプランコンテスト","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"８名の方がということですけれども、この８名の方で品川区の方がどのくらいいるのか教えていただきたいのと、それとこのチラシのほうの実行委員会メンバーのエムティーワーク有限会社、ここの会社はどういう形でこういうふうに入っているのかということと、それとそもそも論なのですけれども、この施策は、このウーマンズビジネスグランプリは誰のためにやっているのか、そこを教えていただけますか。","respondent":"山崎ものづくり・経営支援課長","answer":"ウーマンズビジネスグランプリは誰のためですけれども、本日、レジュメの１枚目に、区内での創業を促進し、区内産業の活性化を図るのだという最終的な目標からすれば、区民の皆様のためであり、区内産業の活性化ということが最終的な目標ではありますけれども、今回。","voiceIndex":41,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"これに関しては、たしか予算・決算特別委員会でもお伺いしたと思うのですけれども、半分入ってよかったですね。実際３回目なのですけれども、１回、２回やっているわけですから、これの具体的にこれこれこういう形で、グランプリの中に入ったところが品川区で起業支援はこうなっていますという具体例を教えていただけますか。","respondent":"山崎ものづくり・経営支援課長","answer":"そういう意味では、過去１回、２回と実施しておりまして、このウーマンズビジネスグランプリのファイナルで８名ずつということですけれども、トータル過去２年で１６組のプランの提出の中では、区内の方が２名でした。","voiceIndex":43,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"その２名が創業した会社は、具体的にどうなっているかというその成果、こうなっていますという報告をしていただきたいです。","respondent":"山崎ものづくり・経営支援課長","answer":"１つ目のものが、エージレス世代のファッションビジネスということで、やはり女性のデザインというか被服、洋服の部分ですけれども、冠婚葬祭をテーマにしたビジネスなのですけれども、テレビショッピングなどにも出演されて、起業で行って頑張られているというような状況が１つ。","voiceIndex":45,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"品川を目指して、品川区でグランプリを取れたらすごい企業になったというのも一つあると思うのですけれども、区の行政としてはやはり品川区の女性起業を育てるという意味でこの施策が基本的にあると思うので、その辺のことをいつも頭に入れつつ、事業を続けていっていただきたいと思うのですけれども、それはいかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"ということは、半分はそれ以外の方ということなのですけれども、例えば１例ですけれども、他区の方のビジネスモデルについて、傘を閉じるときに、ワイヤーで雨でべたべたしたときに、入り口に入るときにすぐすっと入るようなカバーを考案しているアイデア商品の一つですけれども。","voiceIndex":47,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"最後に会場なのですけれども、今回、スクエア荏原でやるではないですか。今後、こういうウーマンズビジネスグランプリみたいなものも、昨日出た大崎のああいうホールを使っていく形になっていくのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"こうしたビジネスモデルがいろいろビジネスとして成功する過程の中の途中で、例えば事務室をお借りして本拠地をつくりたいとか、そういったようなニーズには、インキュベーションの事務室なども連携しながらさまざまな機能をマッチングさせていただいて、区内産業。","voiceIndex":49,"id":"exchange-020"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"その武蔵小山創業支援センターとの関係性と成果を改めてお聞かせいただきたいのと、もう一点が、これは賞を取った人は副賞ということで何らかしらのものがあるようですけれども、この副賞というのがもしわかったら、どのようなものがあるか教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"１例では創業のアイデアづくりから、事業計画をつくって資金計画をつくるというような一連の起業セミナーということで、ＭＵＳＡＫＯ一期生、二期生という形で呼称しておりますけれども、そうしたある一定期間、３カ月間。","voiceIndex":51,"id":"exchange-021"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やはり今まで区外でしたけれども、品川区はこれだけ一生懸命やってくれたから品川に住もうとか、品川で起業しようというふうに思ってもらうというのが大事だと思うので、その点をぜひ、例えばグランプリの方たちとかに、副賞という言葉がいいのかどうかわからないですが、手厚く支援ができるような仕組みづくりとか、そういったものをぜひ検討して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"いろいろご説明を伺っていましたけれども、このウーマンズビジネスグランプリはもっと広い意味があるのではないかと私は思ったのです。すぐれたビジネスプランや技術や区内産業だとか、それを通じてやはり女性が社会で活躍できる、またそれを支援していこうと、広くは社会に貢献していこうという視点というのは、ここにどんなふうにあるのか、そこを伺いたいと思ったのです。そこをぜひ伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"所管事務調査のほうでも、女性の視点で、本日、いただいてお話しする予定にしておりましたけれども、そしてある意味起業を支援するというのは、見方を考えれば女性の雇用支援という側面もありまして、そうした中の女性の就業・雇用という全体の広い中で。","voiceIndex":54,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味では、全国から募集をかけるという意味もそこにつながってくるのかと思うのですけれども、３回目ですよね。当初からそういう視点があったのではないのかと思うのですけれども、改めてそこを伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"中塚委員のおっしゃった、広い感覚で女性の創業を支援するというキーから、私ども産業の担当部門としましては、今回はそうした女性の抱える発想とか視点をビジネスモデルに展開して活かそうということでご支援をする一環の中で。","voiceIndex":56,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言。金属アレルギーについても、私も知らなかったのですけれども、今、ステンレスの指輪とかネックレスとかがあって、アレルギー反応が抑えられると。ぜひそういう視点を大事にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-025"},{"speaker":"吉田委員","kind":"意見","question":"さっき少し出たのですけれども、具体的に聞きたいのですけれども、武蔵小山創業支援センターの中のチャレンジショップとインキュベーションルームに空きが出た場合に、このプレゼンテーションの通過者が優先的に案内をされると聞いたのですけれども、その希望者があるのかということと、それから現状を聞きたいです。","respondent":"山崎ものづくり・経営支援課長","answer":"武蔵小山創業支援センターにつきましては、インキュベーションの事務室は８室ありまして、現在満室といいますか、１００％入居しております。","voiceIndex":59,"id":"exchange-026"},{"speaker":"吉田委員","kind":"意見","question":"プレゼンテーションを通ったらご案内できますよと言ってしまっているので、ちょっと器が少ない、小さいと思うのです。それを山崎ものづくり・経営支援課長はどう考えていらっしゃるのか、ほかに考えるのか、期間を区切って次の方に行くのか、どういうお考えなのかを聞きたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"いろいろ創業していただくための場所の提供として、昨日ご案内させていただきました施設ができますと、もう一つそこが第二成長期の企業の、ロケットで言うところの２段目の支援ということになりまして、やはりそういった形で創業支援する場の有効活用という形で考えてあります。","voiceIndex":61,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"ショップとかブースとか、なかなか難しいと思います。先ほどおっしゃった昨日のお話というのは、ちょっとお金がかかると思うのです。その辺お金があれば、ショップもブースも簡単なことではないですか。それでここが空いていなかったら、その企業は家賃分のお金というのをどういうふうに見込むのですか。","respondent":"山崎ものづくり・経営支援課長","answer":"一つとしましては、区の持っているそうしたインキュベーションの資源だけを活用するような説明をしてしまいましたけれども、やはり通常の民間の事務所スペースでありますとか、貸し施設などもありますので、そうした情報を例えば宅建などの情報とリンクさせて。","voiceIndex":63,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"やはり多少決めてしまうというのはおかしいですけれども、今、空き店舗とか商店街とかにあるではないですか。それは、今、恐らく利用がないですけれども、むしろ区が援助するということも、これを通った方に関して、そういう案もひとつぜひ進めていけたらいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-029"},{"speaker":"山元委員","kind":"質問・要望","question":"本当に女性がいろいろなアイデアで、たくさんのお仕事を品川でという、とてもすばらしいのですが、一つはこういう開催されるに当たって、先ほど周知するのがエムティーワークというところがしてくださると言っていましたが、区はここでやりますよとかこんなアイデア、こういう内容的なチラシですか、そういうのは全部お任せして、区は区の施設では配っていないのかということと、それからあとこの当日。","respondent":"山崎ものづくり・経営支援課長","answer":"これまでも、中延のスキップロードですとか、旧東海道の仮店舗、１日単位で借りられるような場所がございまして、そちらのほうで今回と同様のアントレーヌと題しまして、テストマーケティングの場をやってございまして、中延と旧東海道のほうで。","voiceIndex":66,"id":"exchange-030"},{"speaker":"山元委員","kind":"質問","question":"先ほど、参加というか、ここにいろいろな方が見えると思うのですけれども、その辺は業者たちが見にくるというか、どうなのですか。","respondent":"山崎ものづくり・経営支援課長","answer":"昨年、一昨年の１回、２回の状況を伺いますと、そうしたやはりビジネスに関連のある方々が主にそうした周知、あるいは自分の知人がプレゼンテーションをするというような関連のものが多いのですけれども。","voiceIndex":68,"id":"exchange-031"},{"speaker":"山元委員","kind":"意見","question":"やはり子育ての人たちにしてみれば、そういう授乳に対してのいろいろなものとかと書いてあるのだけれども、やはりもっと関係者以外の現場の人たちが、こういうのがあったらいいねというものを感じてもらえるための周知というか、それが大事ではないかと思うのと、それから、今、言ったこのグランプリに入らなくても、こういうものがあるというものをやはり目で見えるというか、何かそういうものがあれば。","respondent":"山崎ものづくり・経営支援課長","answer":"単体のこうしたイベントで終わらせないというつなぎの部分は意識しておりまして、山元委員がおっしゃいましたそのプランの内容ですとかアイデアを、少しわかりやすく紹介するようなことを研究してまいりたいと思ってあります。","voiceIndex":70,"id":"exchange-032"},{"speaker":"向副委員長","kind":"質問","question":"１点だけ。今回、今年の審査員の方の顔ぶれとバックグラウンドを教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"基本的には、書類審査も含めまして、中小企業診断士ということで考えてあります。ファイナルにつきましては、女性起業家同友会の品川区の交流会の会長、それからベンチャー学会の事務局長、それから区のほうからは私どもの中川原部長、そうした方々です。","voiceIndex":72,"id":"exchange-033"},{"speaker":"向副委員長","kind":"質問","question":"わかりました。今、ちょっとどういう審査員の方がいらっしゃるかと伺うと、そういったお金のこととか経営の将来的なビジョンのコンサルティングをしてくださるような方というのは、該当する方というのは例えば税理士だったりとか、会計に強い方というのはどうなのですか、いらっしゃるのですか。中小企業診断士の方ですか。","respondent":"山崎ものづくり・経営支援課長","answer":"１回目、２回目の審査員として変わらないのは区の私でございまして、それ以外につきましては経営コンサルタントの方ですとか、そうした方々を入れまして、実際の基本のところをたたいてきています。","voiceIndex":74,"id":"exchange-034"},{"speaker":"向副委員長","kind":"質問・要望","question":"最後に要望なのですけれども、去年だったか隣同士のお席に座った方が、ファイナルで選ばれていないけれども、自分も起業をしていてという方で、やはり見に来ていらっしゃる方の中では、そういったプレゼンテーションが一つ自分の今後の参考にもなる、お金に関してすごく厳しいプレゼンテーションの指摘を受けているファイナリストの方がいらっしゃいますね。","respondent":"山崎ものづくり・経営支援課長","answer":"わかりました。","voiceIndex":76,"id":"exchange-035"}]},{"id":"topic-04","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"山元委員","kind":"質問","question":"ご説明いただいて、女性の再就職支援ということなのですが、やはりいろいろご相談を受けるのは、保育園に子どもを預けたいのだけれども、仕事が決まらない。今、ここに女性向けの就業相談の実施ということで、これから週１回ということなのですが、今までそれに近いような相談を受けることというのはあったのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"区の全体の女性の就業支援という意味では、子育ての部門とか福祉の関連の部門でそうした分野もやっておりまして、それぞれの分野で一定の成果を見せてきているというような状況です。","voiceIndex":87,"id":"exchange-036"},{"speaker":"山元委員","kind":"質問","question":"これからですので、いろいろ試行錯誤しなければいけないと思うのですが、特に、今、言ったように、子育て中の人、いろいろ技術をお持ちの方もいらっしゃるけれども、なかなか子どもがいるからということで、これからできるのでこれからでしょうが、やはり場所的に要するに区役所の中にそういうコーナーを設けるのでしょうかということと、それから、今、言ったように。","respondent":"山崎ものづくり・経営支援課長","answer":"相談コーナーの設置は、今、ものづくり・経営支援課で経営支援の相談のブースがあります。そちらの一つを活用する形ということを考えてあります。","voiceIndex":89,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"女性の再就職支援ということですけれども、初めに伺いたいのは、この女性の再就職を拒んでいるものは何か、原因をどう考えているのかと、区の見解をまず伺いたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"一般的には女性の再就職を拒むというか、女性は男性に比べて人生のライフサイクルの中で、やはり結婚なり子育てなりというところで、１つの企業にずっと勤め上げることがなかなか困難な状況が男性と比べてあるという認識はあります。","voiceIndex":91,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"女性の再就職、逆に続けたかったけれども続けられなかったということも含めて、拒んでいるものが何なのか、原因をしっかり明らかにして、対策を考える際には区でできるもの、都との連携が必要なもの、もっと国レベルのもの、それはいろいろあるかとは思いますけれども、まず拒んでいるもの、原因は何なのか、そこをしっかり明らかにしていくことが必要だと私は思いますので、改めてそこを伺いたいのと。","respondent":"山崎ものづくり・経営支援課長","answer":"区としましても、そういった女性の抱える課題についての認識は先ほどのとおりです。したがいまして、中小企業の経営者の方々などを対象に、ワークライフバランスの考え方をやはりご理解いただくために、これはきめ細かくシリーズでやってあります。","voiceIndex":93,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"サービス残業であれ、解雇の問題であれ、使い捨ての問題であれ、そういうことで企業に対しても物を言っていくということが、私は女性の再就職支援、また出産や育児や家族の環境で辞めざるを得ない状況になっていくのを防いでいくことにつながってくると思いますけれども、大企業についてはどういうふうに対応しているのか、ブラック企業を正していくその役割も。","respondent":"山崎ものづくり・経営支援課長","answer":"そのうち０.３％の大企業を除いて、そういった状況です。地元の区民の皆様のお顔、それから中小企業の方々の支援というのが第一義的な私どもの使命だと考えてございまして、そうした意味では先ほど申し上げたようなことの周知に努めてまいりたいと考えています。","voiceIndex":95,"id":"exchange-040"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もう一方の子どもがある程度成長した後の方たちの再就職となると、例えば学校に行っている時間帯とかを基本的に働きたいとなると思うので、そうするとどうしても区内企業というか、家の近くでの就職を求める方たちが多いのかと思うので、ここにも少し求職者が抱える悩みというのが出ていますけれども、何が彼女たちに求められるのかということは。","respondent":"山崎ものづくり・経営支援課長","answer":"例えばひとり親の方の自立支援プログラムについては、最終的な到達が就労を通した自立というところで向いているものでございまして、そうした連携をとってまいりたいというようなことと、あと、その企業内の保育所の考え方などもありまして。","voiceIndex":97,"id":"exchange-041"},{"speaker":"石田（し）委員","kind":"提案","question":"ぜひ調査も含めて、できる限り現場の声がやはり一番だと思うので、聞いていただければと思います。もし皆様がやる気があれば、そういうのをやってみてはどうですかという提案というのを僕はしてもいいのかと。そういった意見というか要望です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"言葉にするのは難しいですけれども、確かにタイやベトナム、いろいろなものづくりのビジネスの活性化というのは大事なのですけれども、仕事も技術も海外に行ってしまっては、町場のところがだめですから、販路の拡大はわかりますけれども、産業拠点は国内に置いて、地域経済を大事にしていくという視点というのは、貫きたいと思いました。","respondent":"渡辺委員長","answer":"ほかよろしいですか。全てにお答えできるかはわかりませんが、十分検討します。","voiceIndex":102,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"このしながわ水族館なのですよね。何と言うのでしょうか、確かに僕も水族館は好きですから。ただ、教育施設として始まり、今、どうあるべきなのかという議論が続いているのも承知はしているのですけれども、本来観光としてつくったものではないですし、子どもたちに教育施設としてつくってきた背景があるから、ちょっとここはまた考えて、後から言います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2690#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":36998,"voices":113}},{"id":"h26-20140225-7","meetingId":"h26-cm02","date":"2014年2月25日","dateIso":"2014-02-25","committee":"厚生委員会","time":"午前１０時００分～午前１１時２１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の「品川区障害者計画策定のための基礎調査の報告について」","agenda":"の「品川区障害者計画策定のための基礎調査の報告について」","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"基本的なところからお伺いしたいのですけれども、一番最初の表書きに書いてあるのですが、「障害者基本法に基づく障害者計画と障害福祉計画を一体的に策定する」とありますけれども、これは通常のやり方なのでしょうか。そこのところを教えてください。","respondent":"中山障害者福祉課長","answer":"それとあわせて、障害福祉計画は、実は３年ごとに量の見込みを立てて目標値を定めるものとされています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"障害者計画に基づいて３年ごとに障害福祉計画を策定するのが一般的なやり方だというご説明だったと思いますけれども、昨年、ある障害者の団体の方からもご相談を受けて、この障害福祉計画という数値目標を定めたものが品川区にはまだないというお話だったのですけれども、今回、それが策定されるということで、多分、皆さん待ち望んでいらっしゃるかと思いますが。","respondent":"中山障害者福祉課長","answer":"今回のアンケート調査の中では、どういったサービスを利用したいかという利用調査になっています。ですから、例えば重度訪問介護で何時間以上欲しいというような数字の聞き方はしてはいないところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"区長も、障害者のことに関してはこれから力を入れるということをさまざまなところでおっしゃられているので、そこのところは非常に一番ネックになってくるのかと思いますので、ざっくりした聞き方で申しわけなかったのですけれども、できるだけそこら辺の意見を、このアンケート、もちろん基礎調査も大事だと思いますけれども、各種団体のいろいろな意見を、今日も午後に話を伺いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問・要望","question":"この障害者計画をつくって、３年ごとの見直しの障害福祉計画をということですが、今回、昨日まで障害者計画の策定委員の公募が終了していますけれども、そこと障害福祉計画をつくっていくその先のスケジュールみたいな大きなもの、計画をつくって、その同じ年に福祉計画ができていくのか、それができてから改めて数値目標を入れたものをつくっていくのか、そこら辺の大枠の計画が見えないので。","respondent":"中山障害者福祉課長","answer":"その障害福祉計画の中では、平成２７年度から平成２９年度の具体的な数値目標を載せていくことになっていくと思います。","voiceIndex":10,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"そうすると、障害者計画は、１０年間ぐらいとか、どのぐらいのスパンのものなのかということと、今、あくつ委員からありましたけれども、障害福祉計画については数値量より目標値を入れるということになれば、先ほどあくつ委員が言ったようなニーズの量は必ず把握していかなければいけないのですけれども、それを具体的にはどのようにされていくのでしょうか。","respondent":"中山障害者福祉課長","answer":"それは、周りの支援してくださる方の家庭環境もあれば、公的サービスとしてどこまで出さないとその方が必要な支援ができないかというところもありますので、そこはむしろ、例えば在宅生活を豊かにするために重度訪問介護なども、当然。","voiceIndex":12,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど、サービスの利用のところで、この調査でもありました「一番不安なこと」は、自分が何かあったときに介助を頼める人がいないというような７ページの表記などを見てみると、決して重度ではなくて、障害を持っている方が家族にいたときに、年老いた方は特にそういった親御さんがそうだという状況もあるし、若い方でも何があるかわからないといったときに、それぞれと。","respondent":"中山障害者福祉課長","answer":"この間、法律自体も変わってきたので、職員の説明が不十分だったところもあるかもしれませんし、逆にパンフレットもずっと見直しをしないできましたけれども、これからはどういったパンフレット、あるいはホームページも活用して情報提供していくか、丁寧な情報提供がないと。","voiceIndex":14,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"その中で二つお伺いしたいのは、先ほど施設の方たちにも外出を充実してほしいというところがありました。そのギャップが私にはよくわからないのですけれども、そこについて、このアンケート調査からはどのように導き出されているのでしょうか。","respondent":"中山障害者福祉課長","answer":"私が以前、委員会で、卒後の対策としての受け皿は足りていますと申しましたのは、実際の今ある区内の生活介護、あるいは就労継続支援Ｂ型、そういうところのあき状況と今後の卒業生の進路の見込みを合わせて持っておりますので、その中で要するに行き場がないということはない。","voiceIndex":16,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"私たちが当事者の方から聞けば、もう高年齢、頭打ちで入れないというところだけれども、行政としては数を見たら合いますよと言うことについては、理解を求める作業が足りないのかと思いますので、そこは手厚くしていただきたいと思います。それは要望でお伝えします。どういう取り組みを進められますか。","respondent":"中山障害者福祉課長","answer":"１点目のイベント等の外出というところでは、大きな区の行事などでは、施設の職員の誘導のもとに入所者の方もいらしてはくださっているのですが、例えばそれが個々の団体の取り組みであったときにかなっていないかなという実情は理解できます。","voiceIndex":18,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"障害者計画の策定ですが、既に要綱ができているかと思いますけれども、ここには必ず教育委員会が入るべきだと思いますが、そこは確保されているでしょうか。","respondent":"中山障害者福祉課長","answer":"計画策定委員会には教育委員会も入ります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"渡部委員","kind":"質問・要望","question":"今まで障害者基本計画に基づいてこのようなアンケートは同等レベルでなさったことが過去にあったのですか。不勉強でわからないのですが、どういう時期にどのようなアンケートがあったというのを、もしわかれば教えていただきたいのですけれども。","respondent":"中山障害者福祉課長","answer":"アンケートは申しわけありません。最初はつけようかと思ったのですが、かなり膨大なものだったものですから、今回は割愛させていただいてしまったのですけれども、後ほどお配りいたしたいと思います。","voiceIndex":22,"id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"であれば、この数字を見せていただいていても、相当数の回答いただいていて、何よりも大事なのは、自由意見をつらつら見させていただいたのですけれども、結構、報告書ですから、集約はされていると思いますが、皆さん、それぞれ、やはり個々の対応が必要な方々だと思いますので、いろいろ細かく書かれている方もいるのですが、やはり生の声だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"},{"speaker":"たけうち委員","kind":"確認","question":"確認を含めてですけれども、一応、机上配付されたこれは差し替えですね。これを今見ていたら、３番の施設入所者のところの回収数が、前にいただいたのは１４件になっていたのが１１４件、ここだけでいいのかの確認と、あとは、在宅とか施設入所者の回答率といいますか回収率に比べると、発達障害と高次脳機能障害の方のほうが少ないのですけれども、これは何か理由というか、つかんでいるものがあれば。","respondent":"中山障害者福祉課長","answer":"すみません、資料を途中で差し替えさせていただきました。変更点は、ここの施設入所者の１１４件が１４件になっていたところと、それから１８歳未満の方の数字が抜けておりましたので、それを盛り込みまして、新しい資料とさせていただいたところです。","voiceIndex":25,"id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。郵送と団体を通じてのその違いによってということですね。そういう面でいえば、団体の方を通じてでも結構なので、また意見を、特に回収率が低かったところの人たちの意見も少し、もうちょっと踏まえていただくような工夫もまたお願いしたいのと、あとは、一応、この障害福祉計画を策定するための策定委員会を設置されるということでよろしいですか。","respondent":"中山障害者福祉課長","answer":"それからスケジュールですが、３月に１回設ける予定です。その後、年が明けてから、まず３月の段階ではこのアンケートの報告をしながら、今後のスケジュールを考えていただいて、年度が明けましてから、おおむね３回から４回、最後は報告ということになると思います。","voiceIndex":27,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今の策定委員のメンバーについて、私もちょっと。医療関係者や障害者関係者等々がメンバーで、何人くらいの構成で、障害者の団体の皆さんからは、私たちのことを私たち抜きで決めないでという声がいろいろ出されていると思いますけれども、当事者を厚く入れていくところなどはどうなのでしょうか。","respondent":"中山障害者福祉課長","answer":"それで実際の委員の構成については、これから各委員をお願いしていくところですので、まだ大ざっぱなところではありますが、１５名以内ぐらいの委員構成になろうかと思います。","voiceIndex":29,"id":"exchange-014"},{"speaker":"鈴木（博）委員","kind":"質問","question":"簡単に２点だけお伺いしたいのですけれども、一つは１３９ページと１４１ページですけれども、この「障害に気づいた時期」が、身体障害で「生まれたとき」が５４.５％で、その後、「０歳」が３２.５％になっていますけれども、その次のページの身体障害で「障害がわかったきっかけ」が「生まれて間もなく知らされた」「家族や周りの人が気づいた」というように分散していますけれども。","respondent":"中山障害者福祉課長","answer":"「生まれて間もなく知らされた」というのは、明らかに重度の脳性麻痺の方ですとか、医療的なところで知らされたケースが４５.５％、逆に「家族や周りの人が気づいた」というところが、そういう発達の成長に合わせて。","voiceIndex":31,"id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それと、もう一つですけれども、今、東京都の福祉保健局で、発達障害の子どもに在宅支援で訪問看護を小児科医がするようにと働きかけがいろいろ行われていますけれども、実際、これを見てみると、実際の障害者の方とか家族の方で、例えば在宅のその訪問診療、家でワクチンを打つとか、医師が在宅でやるような、今はすごくそういうことをやりましょうという動きはありますけれども。","respondent":"中山障害者福祉課長","answer":"ただ、これは、全体的に聞いたので、声としてその部分がダイレクトに反映されている結果にはなっていないのではないかと思っています。","voiceIndex":35,"id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"先ほどの回答のところですけれども、2)の「施設に入所している方」が７４.３％で、１１ページで「調査票の回答者」ということで、身体障害者の方たちの家族の方が１５.８％で、知的障害の方は家族が５４.８％となっていますけれども、施設入所の方たちはどういう方が答えられているのか、施設の方たちが読んで、「誘導」という言葉は変ですけれども。","respondent":"中山障害者福祉課長","answer":"９５ページに施設の方で「この調査票に回答していただく方はどなたですか」というような構成が出ています。","voiceIndex":37,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"２点。ですから、ワードとＰＤＦと併用でパブリックコメントを求めていただきたいということは、これは必ずしていただきたい。障害者計画策定委員会は、当然、公開だと思いますが、今、ほとんど品川区は本当に努力をしていただいて、そこに出された資料も添付していただく、議事録も早目、早目に出していただくことができているので、それは同じようにしていただけるのかどうか、確認させてください。","respondent":"中山障害者福祉課長","answer":"実際に来年度、計画のパブリックコメントをするときには、そういった配慮をするようにしたいと思います。それから、委員会は基本的には公開をしていくつもりですし、同じように資料等の提供もしていくということになります。","voiceIndex":39,"id":"exchange-018"}]},{"id":"topic-02","title":"の「品川区における障害者就労施設等からの物品等の調達方針」","agenda":"の「品川区における障害者就労施設等からの物品等の調達方針」","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"１点、このリストの中で物品を見たときですけれども、最初の説明ですと、「物品等」というのは「物品と役務」とありますが、これを見ると、物品と役務がごちゃごちゃに入っているというか、見るほうにとっては別にこれで構わないのかもしれないですけれども、若干、私は見にくいかと思ったのですが、いわゆる契約の部分と物品、どちらも契約なのかもしれませんけれども。","respondent":"中山障害者福祉課長","answer":"今、最新バージョン、これからネット等で配信するものについては、物品の種類をそれごとにソートしています。例えば最初に食品類が来て、その後に日用雑貨、印刷製品というふうに、項目ごとにくくるようにしております。公表についてはそういう形でやっていきたいと思います。","voiceIndex":46,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"今の４番の「物品等の調達目標」ということで、私には調達目標のイメージがよくわからないのですが、平成２７年度、どういうふうに示されるものになるのでしょうか。","respondent":"中山障害者福祉課長","answer":"これは実際に運用していきながら、一方で就労の場にも、区としてこういうものがあれば受注がもう少しできそうだという、やはり両輪で進めていく部分があると思いますので、ここの調達目標についても、どういう目標値を持ってくるのが一番効果的であり。","voiceIndex":49,"id":"exchange-020"},{"speaker":"井上委員","kind":"提案","question":"そうすると、「物品等」の中に役務が入っているわけですよね。私、昨年の決算特別委員会で提案したのですけれども、ここで高齢者の就労機会と障害者の就労の拡大というところで、役務、封筒入れの作業とか、随分とそういうところで流動的にできるようなものがあって、そうすると、この法律のほうが優先した形で区の中で整理していくのかと思いますが、その辺のこれからの庁内の検討はどうなるのでしょうか。","respondent":"中山障害者福祉課長","answer":"というのは、うちがまずそれをやってみて、うまく成功すれば、逆に、ほかの課で封入作業はたくさんあると思うので、その中で個人情報の度合いが高くて難しいものもあるかもしれませんが、チラシ等で入れて送るだけのものであれば、十分受注可能だろうということで。","voiceIndex":51,"id":"exchange-021"},{"speaker":"渡部委員","kind":"質問","question":"今、説明を伺いまして、そもそもですけれども、これからどういうルールの中で各自治体が動いていく中で、品川区のこちらに示していただいているそれなりの工房とか作業所の今のキャパシティー自体を課長は考えられて、実際、実働これは１００％だとしたら、今は何パーセントぐらいで稼働していて、では、あと、そういう区の調達方針を出したところで。","respondent":"中山障害者福祉課長","answer":"実際にどういった作業をやっていただくかというキャパシティーの問題ですけれども、キャパシティーがまだいっぱいというところではないですけれども、やはり仕事の頼み方として、突発的なものは対応がすごく難しいというのが。","voiceIndex":53,"id":"exchange-022"},{"speaker":"渡部委員","kind":"質問","question":"わかりました。公表は、何をどういうふうに、どこに公表すべき公表なのか、どこ向けの「公表」という言葉なのか、庁舎内でみんなが情報共有することが公表なのか、それが総務省かどこかに上がっていって何かなるのが公表なのか、区民向けに品川区がここまでやっていますよというのが公表なのかという、イメージが全く湧かないので、その意味合いとの二つを教えてください。","respondent":"中山障害者福祉課長","answer":"公表というところでは、この方針もそうですけれども、結果、これぐらいの受注拡大に努めましたというのは、公に公表していくものになります。","voiceIndex":55,"id":"exchange-023"},{"speaker":"渡部委員","kind":"質問","question":"区のホームページなり、広報なりの形で、当然、みんなに、こういう仕組みになって、こういうふうにやっているんですよというような公表だとするのであれば、だとすれば、区はこれだけやっていると言うよりも、このカタログではないですけれども、写真入りでクッキーですとか何だとかこういうのがどこどこで買えますというのを一緒に合わせてアナウンスできるような公表の仕組みを考えていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"},{"speaker":"たけうち委員","kind":"意見","question":"「障害者優先調達カタログ」の別紙２の下のほうに、「随意契約を積極的に活用すること」とありますけれども、もう１枚めくったところのリストに、過去１年間の受注実績の部分で、「無」もありますけれども、ほとんどが「有」ですけれども、これはそうすると、今までもこれは随意契約だったのではないかと思いますけれども、その辺と、今後、この随意契約、どうしてもほかの契約を考えると。","respondent":"中山障害者福祉課長","answer":"この過去１年間の受注の有無で「有」が多いというのは、この間も、この通達方針をつくる前から区内で、例えば何かお茶菓子が要るのであれば、かもめ工房のお菓子を買うようにしましょうとか、それぞれの主管課で障害者の就労のことを考えて対応してきてくれたところです。","voiceIndex":58,"id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この調達方針で、受注を安定的に確保していくところですけれども、これを受けて働く障害を持たれた皆さんの工賃も上がっていくことになっていくのでしょうか。それで、障害を持たれた方が働いてもワーキングプアがほとんど、全国にも６０％を超えているところでも、これを受注して工賃が上がっていくことになるのかということと、品川区での平均的な工賃の額は、もしわかれば教えていただきたいのですが。","respondent":"中山障害者福祉課長","answer":"就労支援Ａ型になると、これは雇用型なので、やはり１０万円台に乗ってくるというところです。今、東京都も何とか工賃アップをということで、東京都もそうですけれども、区でもこういった安定的な受注をしていくことが、お一人おひとりの工賃につながっていくかなと思っています。","voiceIndex":60,"id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"受注がどれだけ来るかはまだわからないですけれども、もしもたくさん来たときに働く皆さんの無理のない形にしていくのは、配慮されるのかどうかを伺いたいのですが。","respondent":"中山障害者福祉課長","answer":"あくまで無理があっては元も子もありませんので、受注側が受注できる量を安定的にできるだけ供給する体制がつくれていければいいのかなと考えているところです。","voiceIndex":62,"id":"exchange-027"}]},{"id":"topic-03","title":"の「品川寮の閉鎖について」","agenda":"の「品川寮の閉鎖について」","exchanges":[{"speaker":"井上委員","kind":"質問","question":"その施設が取り壊しということですけれども、今、そういう住宅がとても、何かほかに品川区が借りるとか、活用するとか、そういう検討はないのか、そういうことはもう法的に不可能なのかということと、あとは、取り壊しをしたのであれば、その跡はどのような形にその土地がなっていくのでしょうか。","respondent":"竹田生活福祉課長","answer":"敷地につきましては、隣に建っております浜川荘と同一敷地内に建っておりまして、土地の所有者が特別区人事・厚生事務組合になっておりますので、更地にして特別区人事・厚生事務組合にお返しする予定です。","voiceIndex":68,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"その特別区人事・厚生事務組合に返したときに、何かもう既に、ずっとあけておくわけはないと思いますから、計画が見えているところはどうなっているのでしょうか。","respondent":"竹田生活福祉課長","answer":"今後の使用目的等は、まだ特別区人事・厚生事務組合により示されておりませんので、今後、協議して有効な活用をしていきたいと考えております。","voiceIndex":70,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問","question":"品川寮ということで、私も何度か伺ったことはありますけれども、これは東京都と特別区で共同で運営されていたということですが、制度として知っておきたいのですけれども、あれは指定管理になっていたと思いますけれども、それはどこがそもそも雇用しているというか、雇っているかということと、あと品川区の使用実績、品川区がお願いしていただいた方の使用実績がもし今わかればということと。","respondent":"竹田生活福祉課長","answer":"それで第３ブロックの中での施設の順番ですが、路上生活者が多い順に担当することになっておりまして、当初は平成１３年から始まったのですが、一番最初が最も多い大田区、次が渋谷区、その次が世田谷区、その次が品川区と回ってきましたので、次は最後の目黒区ということで。","voiceIndex":72,"id":"exchange-030"}]},{"id":"topic-04","title":"の「品川区新型インフルエンザ等対策行動計画」のパブリックコメントの結果報告","agenda":"の「品川区新型インフルエンザ等対策行動計画」のパブリックコメントの結果報告","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"自分も計画書をつくっているのに手間がかかってしまったのですけれども、一般的な周知としては、今、新型インフルエンザよりも、むしろ今は麻疹のほうが問題だと思いますけれども、新型インフルエンザに関して、これは余り関心が高くないので、だから結局、このぐらいの数は、ある意味でしようがないのかなという気もするのですが、とにかく地道に計画を推進して、適宜。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3380#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":25527,"voices":91}},{"id":"h26-20140225-8","meetingId":"h26-cm02","date":"2014年2月25日","dateIso":"2014-02-25","committee":"建設委員会","time":"午前９時５９分～午後３時２１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"しながわ水族館の入館料改定","agenda":"しながわ水族館の入館料改定","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"簡単なことなんですけれども、なぜ大人料金だけ改定なんですか。それだけ。","respondent":"多並公園課長","answer":"料金の改定に当たりましては、まずサンシャインシティが、大人料金もしくは子ども料金も含めた１０円単位の値上げもいろいろな形でまずは案を考え、シミュレーションいたしました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"それで、８％に変更になることに伴いという表現ですけれども、水族館の経費も当然３％上がるわけですよね。だから、この５０円の値上げで吸収できるとは思わないんだけれども、その相差は、例えば品川区の税金を投入していくなり、要するに、収支のモデルについてどうお考えなのでしょうかということをお聞かせください。","respondent":"多並公園課長","answer":"今回のこの値上げにつきまして、まずはサンシャインのほうで、どのような増税に伴う経費と、あとは収入についてなるかシミュレーションいたしました。上げない案も一つあったんですが、それは非常に難しいということで、上げる案で考えました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"例えば、地域センターの集会室を利用する利用料とか、何か全部転嫁されてしまうと、ありとあらゆるものが公共料金も上がってしまうということなんですけれども、その辺の考え方というんですか、増税が響いてくるところ、響いてこないところ、させないところ、やらざるを得ないところ、その辺の、難しい……。でも、その辺が議論的にはどこかであったんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"そういう議論というのは、これだけで済むのか、ほかにまた出てきて議論するのか。ほかにはないですか。区民が利用する部分、利用料なんかにはね返ってくる部分というのは、ほかにないのかどうかということです。","respondent":"安井土木管理課長","answer":"公園ですとか、一般的に公の施設の関係は、条例改正を出していないというふうに私は記憶しておりますので、そういった意味で消費税改定に合わせて料金を改定するというのはないのではないかというふうに思っております。","voiceIndex":17,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"提案","question":"金額的にどうかというところはないんですが、私は消費税増税分を、いろいろ検討はされたと思うんですが、利用料、区民に負担を転嫁するのではなくて、いろいろ財政的に大変ということはあるかとは思うんですが、区の負担でやれないかどうかということを提案したいと思うんですけれども、いかがでしょうか。","respondent":"多並公園課長","answer":"もう一度、先ほど、料金改定の件でお話ししましたが、区民料金等については据え置く形ですので、９５％が区外の方の利用があるこの施設の中では、区民への影響というのは非常に、本当に最小ぐらいの形ではないかということで考えてあります。","voiceIndex":19,"id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"先ほどの答弁の中で、大人の割合が７０％あります。この７０％という割合で言うと、品川区外と区内での、ここの分類でいう割合を出しているのでしょうか。そうなると、仕方のないことだと思うんですけれども、でも、一般、しかも区外の方に対してだけを上げるということは、どうもつじつまが合わなくはないですかという考え方、それはいかがでしょうか。","respondent":"多並公園課長","answer":"今回の大人料金のみ、区内は上げないところですけれども、これはどちらかといいますと、サンシャインの全体のいわゆる先ほど事務の軽減という話をしましたけれども、そういうものも全体で勘案し、大人料金のみ５０円上げるのが妥当だろうというところで。","voiceIndex":21,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"今のご答弁の中で、区内在住の方が５％、すごい少ないですよね。これは認識を改めなければいけないと思うんですが、これはちょっとずれてしまうと思いますけれども、この５％を上げなければいけない。例えば、クルージングと一緒にすると割引とか、何かそういう形で還元できるような方法も一つの考え方ではないかなと思うんですが、そこら辺のお考えをお聞きしたいと思います。","respondent":"多並公園課長","answer":"契約の見直しというところからお話ししますと、実は今年度、経営改善委員会とか、庁内で検討組織を立ち上げまして、各課連携事業、またはサンシャインシティとも契約のいろいろな見直しを図れないかということを協議してまいっております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"実際にやって、実績も少し出てきましたよというお話なんですけれども、消費税が上がるということでは、やはりそれだけの付加される部分があるので、それを考えていると思いますが、なるべくそれを抑えるということも、消費税が上がってしまうわけですからしようがないので、それとは別としても、区として自分でできるものについてはちゃんと手立てをして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"今の質疑応答で思ったんですけれども、確認なんですけれども、要は５０円の料金改定で、消費税の増税分の支出をカバーできると経営判断したのでしょうかということが１点と、もしそうであるならば、消費税は上がるけれども、こういうふうに抑えましたという説明か何かを考えて、区民なり入館者の方々に、本来は、例えば３％全部上げるところなんだけれども、経営努力をしましたという表現をしたほうが。","respondent":"多並公園課長","answer":"今の改定の趣旨ですけれども、サンシャインと、何しろ私も計算するところを見ましたけれども、ここでカバーできるというところで、ただ、入館者数がどれぐらい来るかというのは読めないところがあるんですけれども。","voiceIndex":26,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"だから、うまくサンシャインと協議をしていただいて、料金改定のご案内なり、本来はこうすべきところ、経営努力でこうしました、だからご理解くださいという丁寧な説明をしたほうがいいんじゃないでしょうか。","respondent":"多並公園課長","answer":"委員のお話のとおりです。やはり利用者の方にはご理解いただいて来ていただくというのがもちろん重要なことですので、そこの事前の周知も含めて、なるべく丁寧にさせていただきたいと考えています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"こんの副委員長","kind":"確認","question":"今、伊藤委員のご質問にちょっと関連するんですが、いわゆるこのご案内がどのように出されていくのか確認だけさせてください。","respondent":"多並公園課長","answer":"は広報、区の広報で４月１日号でご報告いたします。もう一つは、ホームページで、３月中旬にはホームページでお知らせするという形をとらせていただこうと考えています。","voiceIndex":30,"id":"exchange-011"},{"speaker":"こんの副委員長","kind":"質問","question":"これは区内の方向けのお知らせですが、区外の方も含めてどうされるのかというのが１点と、あと、改定がなされるというのは決まっていくことなので、早め早めの周知が必要かと思いますけれども、そうすると、３月中旬というのは、できる限り早く周知を始めたほうがいいと思いますけれども、いかがなんでしょうか。","respondent":"多並公園課長","answer":"やはり一般的なご利用からしますと、ホームページを見てというのが多いもので、そちらについては、サンシャインと今協議した中では３月中旬にお知らせするという話なんですが、そこについてはもう少し前倒しできないか等については。区のホームページおよびしながわ水族館のホームページのお知らせになるんですけれども、区のお知らせをすると、そのまま水族館のホームページに飛ぶような形になっていますので、両方が見られる形にはなっております。","voiceIndex":32,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区内在住・在勤の方の料金はそのまま据え置きというところは評価したいと思うんですが、皆さんと私は意見が違うかもしれませんけれども、水族館というのは教育的な施設の意味合いがとても、もちろん観光という面もありますけれども、教育的な施設という位置づけがすごく多いのと、今伺ったら、区外から利用されている、どんどんお知らせして利用していただきたいし、また。","respondent":"多並公園課長","answer":"もう１個は、３％という数字がなかなか実は大きい数字で、今回もかなりいろいろな対応をした中で５％のアップまで行くところからいうと、かなり大きい数字とお含みおきいただければと思います。","voiceIndex":35,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面では、もちろん運営の経営の手腕が問われると思いますけれども、どうしてもこういったなかなか難しい運営のところ、教育施設の意味合いをやっぱり大事にしていただく意味でも、今後また値上げとかも起きては嫌なんですけれども、予想されるという意味では、その辺も区としても考えていただきたいなと思っています。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"説明なんですけれども、これ、今までの議論も含めて、消費税という意味であれば、一律１０円とかという形で一律改定ですよと、その一言で終わってしまうと思うんですよ。でも、言わないわけにいかない。でも、部分的に上げると言ったときのお題目をどうするんですかという、そこは慎重に考えて報告しないと墓穴を掘るのではないですかというふうに思うんですが、いかがでしょうか。","respondent":"多並公園課長","answer":"そこがまず全体的なそういう流れがあるということと、あとは、先ほど申しましたけれども、全体のいわゆる収支スキームを見た中で、やむを得ず、今回は大人ということになっていますけれども、ただ、そこは利用者の観点から言えば、委員のおっしゃるとおりのことで、先ほど。","voiceIndex":38,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひこれはお願いしたいと思います。なので、ほかのところの施設が、ほかの自治体を含めてどういう説明をされているのか、参考にしていただくなりして、利用者の納得いく説明をぜひしていただきたいなと思うんです。逆に、詳しくやり過ぎると、いろいろ突っ込み材料満載だと思いますので、そこは納得いくところはどこの範疇なのかということを勉強してよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-016"}]},{"id":"topic-02","title":"五反田ふれあい水辺広場における平成２６年社会実験について","agenda":"五反田ふれあい水辺広場における平成２６年社会実験について","exchanges":[{"speaker":"木村委員","kind":"質問","question":"始められた考え方というのは、やはり水辺にたくさんの方を呼びたいというか、親しんでもらいたいということで始められたことと思います。最初からこれを２年ぐらいの計画でやる予定でいたのか、その辺はどうでしょうか。","respondent":"奥田河川下水道課長","answer":"この協議会の中には東京都なども入っているんですけれども、例えば東京都ですと、隅田川などでも同じようなにぎわいみたいな形の社会実験をやっておりまして、それが大体３年ぐらいかけてやっているということがありますので。","voiceIndex":45,"id":"exchange-017"},{"speaker":"木村委員","kind":"意見","question":"これを３年ぐらいということでいくとすれば来年もやるのでしょうけれども、昨年は大体予想どおりの数字というのか、考えていたようなことが実現されたのかどうか、それをお聞かせください。","respondent":"奥田河川下水道課長","answer":"昨年ですと、３月から５月までということで、大体４０日間ぐらいやりまして、その中でランチの提供ができましたのが、大体２,５００食ぐらい提供できまして、２,５００食提供できたということで２,５００人の方が訪れたというイコールではないんですけれども。","voiceIndex":47,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"これを大体２,５００食ということであれば、もっとこれ以上、２者以上に増やすということは考えられないのでしょうか。そういう出店を増やしていくという考えもあるのだろうか。","respondent":"奥田河川下水道課長","answer":"今回の公募で応募されてきたのが２者ですので、たくさん応募されてくれば、実際は協議会の中で判断していくんですけれども、実現性ですとか、あるいは目黒川のＰＲ、あるいはイメージアップ、そういった地域性とか、アイデアとか、工夫とか、そういった条件を満たすものであれば。","voiceIndex":49,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"社会実験という表現なので、成果、今、２,５００食の提供だったんだけれども、いまひとつ実験に対する成果が見えないので、品川区の見解で結構なので、この社会実験に対する成果はどういうにお考えになっているでしょうかということが１点と、それから、品川区の負担、税負担等がありますでしょうかということと、それから、ここに報告があるということは。","respondent":"奥田河川下水道課長","answer":"ただ、これは将来の見込みですので、今後検討していく中で変わっていくところはあるというふうに考えてあります。","voiceIndex":51,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"確認","question":"改めて品川区の税の負担があるんでしょうかということの確認と、それから、ケータリングカーを呼ぶことは、もちろんそういった意味ではわかるんだけれども、もともとここにそういう飲食を提供する店は入っていないんですか。お願いします。","respondent":"奥田河川下水道課長","answer":"委員からご指摘ございましたように、もっと別の方法でにぎわいを出していけることがあれば、そういったものも当然活用していきたいと思ってありますし、実際に人に来てもらうということがありますので、イベントなどで、今後、期間が長いので、例えば野菜の直売とか。","voiceIndex":53,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"何となくわかってきました。今回はケータリングなんだけれども、さまざまなプランを当然これから利活用協議会の中で検討していって、今言ったさまざまなことも含めてやっていく。わかりました。そうしたら、改めて、これはこれでもちろん進めていっていただきたいのだけれども、やっぱりこれだけではないと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"具体的には公益法人が入っていて、それと一般社団も入っているのかというところをまず教えていただきたいというのと、二つ目が、社会実験ということなので、これは２年や３年やっていいんですけれども、これがある程度の発展ということを、実際には売り上げていく問題なので、利益が出る出ない、実施予定者も当然にビジネスですからもうからなければいけませんし、じゃあ。","respondent":"奥田河川下水道課長","answer":"次に３点目ですが、にぎわいですので、実は河川下水道課だけではなくて、関連する課、特に商業・観光課とも調整してやらせていただいてございまして、今委員からございましたように、河川の管理区域ですので、当課がしっかり主導権を持ってやっていきたいと思ってございまして。","voiceIndex":56,"id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、そこについてはしっかりと主導権を持っていっていただきたいという思いのもとに、しつこく言いますけれども、そこの考え方について、もう１回確認をしていただきたいというのと、あとはやはり、当然にビジネスですから利権的なものが出てこようかと、その辺の調整をかえってやることによってプラスになればいいですけれども、マイナスになっても困るので、その辺の思い、お考えを。","respondent":"奥田河川下水道課長","answer":"その思いということでございましたけれども、やはり目黒川にとって、これは区にとっても非常に重要な河川で、にぎわいを出したり、あるいは水辺に親しんでもらいたいということがありますので、しっかり区として、建設委員会の関連部署から、教育ですとか商業。","voiceIndex":58,"id":"exchange-024"},{"speaker":"原委員","kind":"意見","question":"そうしましたら、もう少し大きく基本的なところの考えを申し上げてしまうと、あとは歴史的なところを言ってしまえば、これはもともと船と言っていますけれども、一番初めに東京都の云々というやりとりの中では、こういった話はなくて、一番先のスタートは災害のためにというような点からスタートしていると思いますので、そこのところに関連して、区の考え方をお聞かせいただければと思います。","respondent":"松代防災まちづくり事業部長","answer":"そういったことを含めて、地域の方々を中心にしっかりとこの辺が進めていければと、このように思っているところです。そういう中で品川区もしっかりとそれを下支え、支援して、さらにこれがよくなるようにしていきたい、このように思っているところです。","voiceIndex":60,"id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"目黒川利活用協議会ということで社会実験ということなんですけれども、今、防災まちづくり事業部長がおっしゃっていた協議会の中で、まちづくり組織、商店街、自治会、地元の町会、東京都、品川区ということなんですけれども、先ほど来より、親水ということと、にぎわいの創出という二つの単語が出てきたんですけれども、今まさに部長がおっしゃったように。","respondent":"奥田河川下水道課長","answer":"例えば、前年度といたしましても、協議会等で既に４回開催してございまして、なるべく皆さんに納得していただけるような形ということでご協議いただいているような形になってあります。","voiceIndex":62,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"実施予定者が２者なんですけれども、これしかなかったのかなと思うんです。呼びかけはどうなっているのでしょう。それと、商店街も、やりそうだったけれどもやらないというところになっているんですね。ここの呼びかけをどのようにされているのでしょうか。","respondent":"奥田河川下水道課長","answer":"ほかにやるような業者がなかったのかということがあるんですけれども、なかなかこういった業界というのは、例えば有楽町の東京国際フォーラムとかのほうがやっぱり立地条件がいいということで、あちらのほうに流れていってしまうということがございまして。","voiceIndex":65,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"厳しいですよね。ずっとじゃなくてもいいじゃないですか。イベントのときにはもうちょっと広げて、５者、何者という形で枠を広げるとか。それで私たちはにぎわい、地域の方たちもにぎわって、地域の商店街の人も参加してもらうということの流れもつくれるのではないかなと思うんですけれども、今の状況だとちょっと、やっぱりお役所的なやり方になりはしていないかなと思うんですが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長、奥田河川下水道課長","answer":"運河も、運河ルネサンス等で見ていただいてわかりますように、少しずつですけれども、運河を使っていい、そういった形になってまいりました。今委員からありましたような、そういった形で野菜の直売ですとか、あるいはフリーマーケット、骨董市、パフォーマーみたいな、そういったイベントなどもまさに検討しておりまして。","voiceIndex":67,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"でも、もう少し工夫、言い方を変えるとか、考え方をちょっと曲げてみるとか、そういういろいろなことをして、なるべくここはいいところだ、何か評判があるね、何かにぎやかになりそうだね、おもしろい場所だよねという、そういう意識づけ、非常に肝心要なスタート時点だと思いますので、ぜひともチャレンジ精神で進めていただきたいなというふうに思っていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やっぱり災害のときどうなのかなという心配が結構地元などにもあるんですけれども、改めて、ちゃんとしているとは思うんですが、災害時の対策というか、よく川などで子どもたちが遊んでいて増水したときに被害があったりとか、そういうのがあるので、どういうチェックがされたり、こういう場所で人を集めるイベントとかをされるに当たっては、今後やっぱり災害時の避難訓練とか。","respondent":"奥田河川下水道課長、多並公園課長、稲田道路課長","answer":"五反田ふれあい水辺広場における安全対策ということなんですけれども、実際、整備は東京都でやってございまして。公園を管理しているものは、警報になったときには、閉鎖をして、閉鎖する際にはまずは利用者がいないか確認した上で閉鎖をさせていただいて。河川の水位の注意水位とかになったらランプがついたりとかしてお知らせするという装置もあわせてついています。","voiceIndex":71,"id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"一言要望だけなんですけれども、もう多分ご存じだと思いますけれども、先ほど、なかなか難しいというご答弁があったんですが、ご存じのように隣接区で一企業というか、一企業体、結構大手なんでしょうけれども、数年前に倉庫会社がレストランをつくったという事例がありますので、粘り強く頑張っていただきたいというお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-031"}]},{"id":"topic-03","title":"品川区防水板設置等工事助成要綱の改定について","agenda":"品川区防水板設置等工事助成要綱の改定について","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"一つには、今回、改定で５メートル以下のところにも助成拡大をされるということですけれども、過去に何回も浸水する地域がどのくらいカバーされるのか、これはピンクの地域に拡大ということなんですけれども、ここの地域以外でも水害の起こる地域でカバーされるのかどうか、その辺が１点と、あと、防水板の助成、本当に集中豪雨などで浸水が起こった地域などでは本当に助かるという声があったんですけれども。","respondent":"奥田河川下水道課長","answer":"こちらの目的といたしましては、津波の対策として防水板を拡大するということでございまして、昨年度、東京都が公表いたしました想定の場合、今後起こり得る最大級の地震を考えたときの津波ということで考えておりまして、津波浸水が想定されますので。","voiceIndex":84,"id":"exchange-032"},{"speaker":"西本委員","kind":"確認","question":"今のご答弁の中で、建築確認をとるときに、こういう防水板が必要ですよと指導されている、その場合に対象外になるんですね。そこで、これから私たち、建物をつくります。住宅を建てますというときに、防水板をつけたほうがいいですよみたいな形になって、つけた場合にはどうなるんですか。","respondent":"奥田河川下水道課長","answer":"あえてそういった危険なものをつくられるということなので、わかられてつくられる形になりますので、そういったところは対象外という形になってあります。","voiceIndex":86,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"どういう形でお知らせをしているんですか。具体的なこういう助成があって、想定が大体５.１１メートルで５メートルぐらい来る可能性があるので、対策はちゃんとしてくださいねというのは、どういうところで周知徹底をされているのでしょうか。","respondent":"奥田河川下水道課長","answer":"これからこういった助成の範囲を拡大していきますよという形で、ホームページですとか、あるいは品川区の広報ですとか、いろいろなところに周知していく形になるんですけれども、津波の浸水想定が昨年度出されたということもございまして、そういった形で指導を徹底というか。","voiceIndex":88,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"そうすると、不動産業の方は一番直接かかわってくるのだろうと思うんです。区内の不動産業の方々とかという、そちらへの情報提供というのは、もうしているのでしょうか。するのでしょうか。","respondent":"鈴木防災課長","answer":"区内の水害等の実績を落としたマップですが、防災課で用意しておりまして、丁目ごとで過去の実績もわかるものがあります。毎日のように建築関係の業者の方が防災課に来まして、ご自分で該当する地区を調べるという形で建築の際に確認をされているようです。","voiceIndex":90,"id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"ＰＲのところですけれども、津波の自主避難マップをつくっている地域がありますよね。そこのところに集中的にこれはこれから拡大したということについてＰＲしたほうが効果が上がると思うんですが、いかがでしょうか。そのお考えをお願いしたい。それから、当然、マンションもあるわけですよね。マンションが防水板を進めた場合については、その他の法人になるのでしょうか。","respondent":"奥田河川下水道課長","answer":"実際に津波避難マップなどでも、そういった低地部で集中的に勉強会なども今年度も実施しておりますので、そうした機会を活用してＰＲしていきたいと思ってあります。","voiceIndex":93,"id":"exchange-036"},{"speaker":"伊藤委員","kind":"意見","question":"だから、特に自主避難マップをつくる地域の方々というのは、当然、津波対策意識が高いわけであるし、それから、ある程度そういう想定がされることも明確になっているわけだから、やっぱりそこについては集中的に新しい事業になりましたということについてはＰＲするべきだと思うんですが、もう一度答弁をお願いいたします。","respondent":"奥田河川下水道課長","answer":"委員からございましたように、そういった低地部のところにつきましては、個人のお宅、マンション等も含めまして、重点的にＰＲしていきたいと思っておりまして、そういう形で防水板の設置、工事の助成などを拡大していきたいと考えています。","voiceIndex":95,"id":"exchange-037"}]},{"id":"topic-04","title":"「所管事務調査」を行います。 午前中に、不燃化特区の事業実施状況","agenda":"「所管事務調査」を行います。 午前中に、不燃化特区の事業実施状況","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"同潤会地区ですか、さっきちょっと歩いているときに見学させていただいたんですけど、いただいた資料で現在、個別意識調査等を行い、共同化に向けた合意形成活動ということで、そういう流れがあるということなんですけれども、ちなみに中で新しく改築でしょうか、新しく建てた建物、それと、先ほど木密整備担当課長のほうで、これが新しくまた建つんですよ、また、おくれちゃうなという。","respondent":"品川木密整備担当課長","answer":"それとも、それなりにやっぱり補償金のほうが出ます。その補償金をもとにして別に一戸建てを買うのか。そういう選択もあり得ますので、そういうところを考えながら、じっくりやっていくというような状況が、新しい建物を所有している方にはあるというような状況です。","voiceIndex":108,"id":"exchange-038"},{"speaker":"大沢委員","kind":"質問","question":"ここの場所は、すみません、不勉強の部分で申しわけないんですけど、建替えが無理で改築はいいということでしょうか。そこをちょっとすみません、教えてください。建替えが無理でも改築はいいのかということをちょっと教えてください。","respondent":"品川木密整備担当課長","answer":"この地区ですが、まだ具体的に何かの事業をやるとかいう都市計画決定をとっていない状況であります。ですので、今現在のところでは、建替えも改修もどちらとも可能というような状況です。","voiceIndex":110,"id":"exchange-039"},{"speaker":"大沢委員","kind":"意見","question":"建替え、改築可能ということで、ちょっと見たところですと、本来なら、密集したところはセットバックをして建てなければいけないと思うんですけど、それがなくてそのままというような新しく新築同様に見えるような家というのは、これは改築ということでいいんですね。","respondent":"品川木密整備担当課長","answer":"そうとはいえ、建物が新しいのにすごく道幅が狭いというような家もご覧いただけたかと思います。そういう住宅に関しては、確かに委員ご指摘のとおり、やはり改築もしくは例えば新しいパネルを張ったとか、そういうようなリフォームを兼ねたというような家かというふうに思います。","voiceIndex":112,"id":"exchange-040"},{"speaker":"大沢委員","kind":"意見","question":"しかしながら、もう目前に迫っている、いつ起こるともわからない、先ほど来、地震の危険ということがあるわけで、そこのところというのは到達点はどのぐらいに行政のほうでお考えになっているか。じっくり、ゆっくりやっていかれる人がいるということをご発言いただいたと思うんですけれども、そういう余裕というのはちょっとないような気がするんですけど、それをどういうふうに。","respondent":"品川木密整備担当課長","answer":"ただ、一つの目標としましては、こちらの木密１０年プロジェクトでコア事業地区として進めていく地区となっております。木密１０年プロジェクト、平成３２年までのプロジェクトですので、できる限りここまでの間に、この事業を進めていきたいという考えで今のところはおります。","voiceIndex":114,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"午前中説明いただいた資料に沿って何点かお伺いしますけれども、まず不燃化特区のところなんですけれども、事業地区ごとに説明会が行われたということで四つに分かれていますけれども、それぞれ参加者というのが書いてありますけれども、ここの中で出された意見、特にこの地域によっていろいろ違いがあると思うので、その辺の地域差とかがあったら教えていただきたいのと。１軒、１軒訪ねて。","respondent":"品川木密整備担当課長","answer":"課題と全件訪問してその後どうするのかという点ですけれども、やはり皆様、いろいろ全件訪問、それから、説明会等やった結果、いろいろな悩みをお持ちの方が多い。資金面を悩んでいる。それから、例えば建替えがきかないところに住んでいる。","voiceIndex":116,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３番目の戸別訪問の意見をもうちょっと詳しく、中身がわかるような報告というのはされないんでしょうか。個々でいろいろ個別でやっていらっしゃるとは思うので。専門家の派遣とか、実際的にやっぱり悩みを一つ一つ解決していくのはとても重要であると思うんですけれども、ある程度まとまって地域で話すのというのは今はもうされていないんですか。その辺をちょっと教えていただきたいのと。","respondent":"品川木密整備担当課長","answer":"個別個別の問題について公表とか説明を出すのかという点ですけれども、こちら、限りなく個人情報に近いような情報になりますので、何かどこかで公表するだとか、そういうことは今のところは考えておりません。","voiceIndex":118,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、視察で見せていただいたんですけれども、本当に一刻も早く対策が進まないとという思いを強く持ったわけですけれども、専門家派遣とかいろいろ手を打ってはいらっしゃるけれども、先の見通しというのはどうなんですかね。特に今日の同潤会のあたりの問題は深刻であると思うんですけれども、見通しというか、その辺はいかがでしょうか。","respondent":"品川木密整備担当課長","answer":"いろいろな多くの事情を抱えている方がいらっしゃるので、その中で先を見てどうなるかとかというところはなかなか見当が立てにくいというところはありますが、ただ、木密１０年プロジェクトの中で、一つ目標に挙げていますのが、不燃領域率、こちらを７０％まで。","voiceIndex":120,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なかなか大変ですけれども、共同建替えとか、そういった部分が１区画でも先に進んでいくことが、やはり個々でなかなかできない部分が進んでいく部分だと思うんですけれども、どうしたらというのはわからないので、引き続き頑張っていただきたいなと思いますので、よろしくお願いします。大きな減災まちづくりのところをお伺いしますけれども、一つは、用地測量の説明会が行われています。","respondent":"藤田都市計画課長","answer":"用地測量の説明会が進んでいくと、最終的には境界を確定するということになりますので、その際に境界立会いの手続のこと、判こを持ってきてくださいとか、いろいろお話をしておりますが、その手続について具体的にどうするのかというような質問も問うていくというような状況です。","voiceIndex":122,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、測量が進んでいく中で、事業認可の施行が進んでいくということで、もう既に認可申請に進んだということは、測量のある程度パーセンテージというか、ここまで測量が個々の境界線とか測量ができたら申請ができるというラインがあるんだったら、教えていただきたいのと。放射２号線の個々のところにおいては、かなり個別の相談が多かったという受けとめ方でよろしいんですか。","respondent":"藤田都市計画課長","answer":"放射２号線のほうですけれども、やはり個別の説明会なので、個々の具体的な中身というのは、細かいところまではちょっと私どもも把握しておりませんが、もちろんそこの席で一般的な話をする方ももちろんあると思いますが。","voiceIndex":124,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"補助２９号線のところは一定いろいろなところにおいて確定がされたので、２ブロック認可の申請を出したということなんでしょうか。そこのところが１点と。希望しても、実現していないところが今後どうなるのか、ちょっとその辺教えてください。","respondent":"藤田都市計画課長","answer":"それらについては、東京都の本庁のほうで２月の頭にも、そういったメンバーをお呼びして勉強会を開いたというようなお話も聞いておりますので、何らかの形でそれぞれの対応ができてきているのかなというふうに感じております。","voiceIndex":126,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"勉強会のほうはぜひ地元のところでやっていただきたい。この間、都庁に、ずっと実現しないのでということで、あわせていろいろの地域の方が１回だけ、お話し合いを引き受けていただいたみたいなんですけども、なかなか、私は放射２号線のところの話をよく伺っているんですけれども、個々の説明会だと、怖くて行かれない。","respondent":"藤田都市計画課長","answer":"冒頭もちょっと説明の中でもやらせていただきましたけれども、地域に相談窓口を一応設けていくというようなことで、今、東京都のほうも準備を進めてあります。区役所に来るのも大変だということもあります。","voiceIndex":128,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ丁寧にやっていただきたいのと、先ほど都のほうで話し合いをと言って、２月４日にいろいろな地域の方が一緒に、ずっとこの間話し合いができないので、一緒に場をつくっていただいて行ったんですが、とにかく不安もいっぱいあるし、さまざまな意見があるし、反対の声もいっぱいある中で、とにかく東京都に対して認可申請をしないでほしいという声を届けたいというふうに、皆さん、忙しい中。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"この専門家派遣実績というのがありますが、補助２９号線沿道はゼロなんですよね。これはどういうふうに見ているのか。まだまだ周知はされていない、説明会でいろいろやっているんですけれども、まだまだ浸透していないのかなというふうに思うんですが、その辺はいかがですか。","respondent":"品川木密整備担当課長","answer":"そうですね。委員おっしゃるとおり、ちょっと実績がゼロということで、やはり１２月から始めているという点で、まだまだちょっと周知が行っていない面も我々にもあるかと思いますので、その辺は少し努力していきたいというふうに思っております。","voiceIndex":131,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"そういう意味では、その報告どうしているのかなというのと。これはどういう違いがあるんでしょうか。そうなると、今、どういう状況なんですか。でも、もうそういう時期は過ぎているんじゃないんですか、時期的に。板挟みになって品川区はどうするんですかというところなんですが、そのいろいろ説明会、勉強会していく中で、どういう変化があって、これからどういうスタンスで区は、進めようとしているのか。","respondent":"藤田都市計画課長","answer":"特定整備路線における説明会と勉強会の違いということでよろしいでしょうか。","voiceIndex":133,"id":"exchange-051"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、もう反対だけでは、ちゃんとした何かの代案があって反対とかそういう形であるならば、一応それも踏まえて考えていきましょうというスタンスは大切だと思うんですけど、ただ単に、反対だけだという運動について、それは今の段階では逆に私は住民を苦しめるだけではないかなと思いますので、そこはしっかり配慮していただきたいなと思います。","respondent":"品川木密整備担当課長","answer":"今後どうするかという点で、先ほど補助２９号線の実績ゼロ件ということで、今後前倒ししている４地区については、老朽木造住宅の全戸訪問していくつもりですので、そういった場で周知のほうをやっていきたいというふうに考えております。","voiceIndex":135,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな意味で露出をして宣伝をして、要は、明るく前向きに地域の安全を確保しながら解決していきましょうというそれも含めて、地域のまちづくりをやっていきましょうというのを伝えていただきたいなと思います。戸別訪問で１点、意見なんですけど、戸別でやっていくとほかの意見を聞けないじゃないですか。そうすると、考え方が煮詰まっちゃうというか、いろいろなことを考えにくくなるんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-053"},{"speaker":"伊藤委員","kind":"意見","question":"これだけの大事業で、それから地区を挙げて反対しているところもあるので、いろいろな意見があると思うんですけど、まず、品川区の体制のことを今ふと思ったんですけれども、これだけのところを環６から環７までとやっていく事業が、あるいは放射２号線、補助２９号線を含めて、相当数の権利関係はまだだろうし、障害もあるだろうと思います。","respondent":"藤田都市計画課長","answer":"この辺については、進捗状況に合わせて、しっかりと区とした体制づくりをしながら進めていきたいというふうに考えております。","voiceIndex":138,"id":"exchange-054"},{"speaker":"伊藤委員","kind":"質問","question":"それで、私が議員になりたてのころですから古い話なんですけど、お名前ちょっと失念をしてしまったんですが、再開発を相当進めていらっしゃる実績がある当時の部長が、いらっしゃったんですね。一つずつ個々のいろいろな生活の実態にあわせて、きめ細やかなと、よく皆さん使っている。どうぞよろしくお願いします。その人の配置のところだけもう１回お願いします。","respondent":"藤田都市計画課長","answer":"東京都のほうにつないだほうがいいケースについてはそのような形をとるということで、信頼関係を構築する上で、区だけ、都だけということだけではなく、しっかりそこの部分も連携をとりながら進めていきたいというふうに考えております。","voiceIndex":140,"id":"exchange-055"},{"speaker":"伊藤委員","kind":"質問","question":"今から２０年ぐらい前のときと、今は随分情勢が変わっているのかもしれませんけれども、ただ、ここの地域の方々、対象の方々等は自分の財産をかけて、生活をかけて、この事業に取り組んでいかなければいけないわけですから、やっぱり不安があって当然なんですよ。それを変なふうに利用することじゃなくて、私たちは。地道な努力なんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問","question":"道路があることでこのまちを救うんだという意見が何人かから出たので、ちょっとその点に関して意見も言いたいし、区のご意見も伺いたいと思いますけれども。防災名目でこの間ずっと説明会でありました。この間はずっと言い続けているんですが、だから、道路をつくることが減災、地域を火災から守ることであるというのは、私は幻想であると思っていますけれども、いかがでしょうか。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"短くつくれとおっしゃいますけれども、道路を長くつくらないと延焼遮断の効果は全くありませんので、この辺のところもご理解いただけたらなというふうに思います。それで延焼遮断効果をしっかりと全体として構築をしていくんだというようなことでありますので、こちらについては整備を進めていきたいと、進めていくべきというふうに考えてあります。","voiceIndex":143,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"防災の延焼遮断効果ばっかりが説明会で示されていて、道路がこの地域にもう１本必要なんだという説明は、私は全然そういう受けとめをしていないんですよね。でも、そうじゃないでしょうと。だから、防災１本で区民に必要だと言って押しつけるのは私は間違いであると思っています。そういった意味で、やはり地域から出ている声、きちんと受けとめて、私はもう立ちどまってやめるべきだと思っています。","respondent":"藤田都市計画課長、片田都市環境事業部長","answer":"震災があった以降、延焼遮断効果があるここの２９号線を整備することがやはり効果が高いので、やはり早くやるべきだよということで特定整備路線に選ばれてきたということで、本当に今すぐやらなければいけない理由というのは、委員、今。都市計画課長が説明したので補足したいと思いますけれども、基本的には放射２号線も２９号線もちょっと繰り返しになって恐縮ですけれども、昭和２１年の戦災復興、当時の写真は恐らく皆さん見ていらっしゃると思いますけど。","voiceIndex":147,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、そこのところを踏まえたまちづくりということが最も求められていると思います。道路は、道路を本当に必要とするんだったら、本当に交通量とか全体的に車がどう流れていて、ここに必要なんだという説明からしっかり、アセスからも含めて全部やって、本当にここにもう１本道路が新たに必要なんだという説明をきちんとした上でする話だと思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-059"},{"speaker":"あべ委員長","kind":"提案","question":"ご発言がないようですので、ここで私から提案をします。２月２１日の委員長会で議長からも実施の報告について依頼を受けており、本委員会としてもまとめを行っていきたいと考えています。そこで、次回の委員会で所管事務調査の報告について、正副委員長で案を提示させていただき、皆様からもご意見を伺った上でまとめていきたいと考えておりますが、よろしいでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":152,"id":"exchange-060"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目は、「予防第１の防災対策を」の質問ですけれども、耐震建替え助成制度を開始している中身の続きのところなんですけれども、木造住宅建替え助成の実績が３８１棟、品川区の木造住宅の耐震化の目標、旧耐震の目標住宅を１万３,０００棟のうちの平成３２年度まで９５％やり切るということになっているんですが。","respondent":"品川木密整備担当課長、藤田都市計画課長","answer":"木造密集地域の不燃化、耐震化を促進してまいります。建替え除却助成につきましては、除却助成で対応が可能なため、今回廃止をする予定です。認可がおりる段階で東京都から情報提供があれば、こちらのほうも速やかに報告をする考えです。","voiceIndex":155,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"最初の１点目、建替えのこれ、質問のためにつくってくださった資料なんですか。要綱が変わるとき、ご説明があったんだけど、この説明がないままに来て、建替え助成の改正、改正の説明、これ、私の質問のためにわざわざつくってくださったのか。本来だったらば、質問がなくても説明なされるところの内容ですよね。この建替え助成がなくなってしまうという、これ、要綱にかかわる中身なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"だから、今後のことだろうなと思っていたんですが、ですけれども、私の質問が出たので、この段になって報告なのかなと。ちょっとその点が１点引っかかっているのと、さっきの最初の質問で、評価をどう考えているのかというところが、これをこっちに変えていきますというご答弁だったので、質問と答弁が食い違っているなと思うんです。だから、その耐震化の建替えの評価を伺ったんです。ちゃんと答えてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問","question":"継続になってないじゃないですか。だって、建替えがなくなって、除却が減になったんですから、継続じゃないと。","respondent":"品川木密整備担当課長","answer":"建替え制度はなくなりますが、その代替という言い方もあれですけれども、建替えを今まで考えていた方につきましては、除却の制度を１００％の制度を使っていただくというような形で、こちらの絵のほうに少し書いて見たんですが、建替えを今までされていた方というのは。","voiceIndex":164,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"私はわかっているんです。だから、そういうきちんと説明してほしかったなと思うので質問したんです。だから、結局は、除却をして建替えのところまではいかないけれども、除却で木造の古いところはなくなると。なぜ言ったのかというと、そこでとどまらないで、やはり建替えのための除却のほうが絶対的に安いんですよ、建替えの助成よりも、計算すると。だから、そういうのをわかってほしいなと思ったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-065"},{"speaker":"西本委員","kind":"質問","question":"よくわからないのがあるのは、除却というだけ、トータル金額がケースによって違うと思うんですけど、この一つのケースを考えたときに、どっちのことなんですか。要は、除却は自分でお金を払ってやります。だけど、先ほどの質問だと、そっちの方が安く済んじゃうから、底辺広げるけど、区としては出るお金が少なくて済むでしょうと。その場合どういうふうに考えればいいのか。","respondent":"品川木密整備担当課長","answer":"そういう意味をもちまして、除却の助成にシフトをしていこうというような考え方です。","voiceIndex":170,"id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"よくわかりました。建替えが廃止になるほうですけど、その費用というのは、こちらのほうがもらえるお金というんでしょうかね、それが大きくなるということでいいんでしょうか。どう考えればいいんですかね。区としてはいろいろな促進をするために、それはパイを取得するために除却のほうが広がっていくべきよねって。","respondent":"品川木密整備担当課長","answer":"今度除却のほうにこれをシフトしていきますと、例えば１００万円しか除却費用がかからなかったと言えば、確かに１００万円しか出ないというような考え方ですが、先ほども言いましたように、耐震化をするところに対して助成金を出すということの考え方で。","voiceIndex":172,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4100#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":60806,"voices":184}},{"id":"h26-20140225-9","meetingId":"h26-cm02","date":"2014年2月25日","dateIso":"2014-02-25","committee":"文教委員会","time":"午前１０時００分～午後０時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２５年度品川区教育委員会事務事業の点検および評価報告書","agenda":"の平成２５年度品川区教育委員会事務事業の点検および評価報告書","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"あまり事前に、最後まで目を通し切れなかったので、ちょっとよくわからなかったんですけれども、教育委員会の中で意見を求め、そして何項目かにわたって指導課中心の意見をいただいているということと、さらに樋口准教授に２つの項目で意見をいただいていると、こういう構成、工程というか、２段になっているというふうに理解していいのかということがまず一つと。","respondent":"齋藤庶務課長、渋谷指導課長","answer":"御殿山小学校で一旦は終了です。今後はまた老朽化、あとは就学人口の動向を踏まえて、別途検討する予定です。したがいまして、この事業の中で改築について出てこないというのは、そういう理由があります。９ページの「教育課題への言及」の部分についてですが、これは専門外部評価委員会が、主に校長先生等のヒアリングを通してやりとりをするということで、実際に子どもからとか、ＰＴＡからとかいうのは今回初めて行ったんですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"それで何ページかにわたって述べていただいたということなんですけれども、でもここの表現では、教育委員会が協議して決定をしたというふうに書いてあるから、教育委員会でここの意見を伺いましょうよ、というふうになったんだと思うんですけれども。その辺はどうなのか、ちょっと教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"少し説明が不十分でした。樋口准教授にお願いしたテーマは、教育委員会で委員の皆様と協議をして決めた案件です。これが一点。決めた経緯としては、教育センターについては昨年度から積み残し分で、どうしてもこれをやりたいということがありました。","voiceIndex":8,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"全く専門外のところは筆が進まないというのは、まあ、ある意味、研究者ご本人にとってどういうことなのか全然わからないですけれども、でもこちら側の期待するところは、推進の立場とか、そうでないとか、研究者としていろいろな立場の方々の批判、ご意見を忌憚なく出していただいて、品川の特徴としているこういう教育推進にいろいろな意味で、功罪も含めてご意見をいただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"塚本委員","kind":"質問","question":"この評価の作業として、３日間行いましたということだったと思うんですけれど、それぞれどれぐらいの時間をトータルかけているのかということをお伺いしたいと思います。","respondent":"齋藤庶務課長","answer":"６年目になりますので定着しておりまして、中身も大分、議論も尽きているところもありますので、そういう意味でいうとこの制度自体、法改正になってもこの制度は続くとは書いてありますけれども、一定程度習熟しているものと考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"そういったことを前提として、この教育センターの維持管理・教育相談事業というのは、教育委員会の意見の中でも取り上げられていて、見直すことが課題であるとか、樋口先生の意見のほうでも同様のようなことが述べられている中で、こちらの最終的な平成２５年度の評価としてはＢということになっているんですけれど、この辺の整合性というのはどういうふうに考えられているんでしょうか。","respondent":"渋谷指導課長","answer":"現在行われている教育センターとしては、従来の業務がきちっと行われているということではありますが、例えばいじめ対策で学校支援チームということで、新たに心理職が指導課に配置されたりというようなことも踏まえて、また施設そのものが新しくなったということで。","voiceIndex":13,"id":"exchange-005"},{"speaker":"塚本委員","kind":"確認","question":"教育委員会として、そういう意見はあるけれどもＢなんですよということなんですか。それとも教育委員会的には何となく、Ａなのではないかとかいう話がある中で、最終的に指導課としてＢという判断だったということなんでしょうか。ちょっとそこだけ確認させてください。","respondent":"齋藤庶務課長","answer":"判断としては、教育委員の皆様の合議での判断で、Ｂということです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"市民科の推進も、教育要領に沿ってしっかりやりなさいと、こういうふうに指摘されているわけですけれども、こういう点についてそれぞれの、教育委員会としてこれからどういうふうにこれらの意見を踏まえていこうとしているのかというあたり、ちょっと伺いたいと思います。","respondent":"齋藤庶務課長","answer":"専門家の意見を踏まえた教育委員会の意見としては、先ほど申し上げた5)スクールカウンセラーの派遣、7)教育センターの維持管理、8)マイスクール八潮の運営についてなんですね。","voiceIndex":17,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"一方の側の推進の立場だけでなくて、それこそ教育委員会の役割をしっかり果たすという、区長部局のほうとはまた違ったスタンスで、教育委員としての専門性みたいなものをしっかり、私がそんなこと言ったら若干失礼ですけれど、ぜひそういうスタンスは堅持していただきたいと思いますので、強くその点はお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"ちょっと細かいことになってしまうかもしれないですが、何点かお伺いしたいんですけれども。特にこの事務事業評価の中のＣの見直しのところで、評価の説明が書いてあるんですけれども、よくわからなかったので教えていただきたいんですが。３０番の学校ヘルプデスク。これを読むと、区の情報システム課と一緒にするからＣということにするのかということ。このあたりの見直しの理由を三つ、教えてください。","respondent":"和氣学務課長、渋谷指導課長","answer":"二つあるのはもったいないのではないかということで、これはＣ評価を受けましたので見直して、来年度からその部分については統合していくということで、考えているところです。それから９９番の友好都市教員の受け入れにつきましては、基本的にグローバル人材養成等で国際理解教育を進めていくという方向性はあるんですけれども、教員招致に関しては、果たして実際ポートランドだったり。","voiceIndex":20,"id":"exchange-009"},{"speaker":"高橋委員","kind":"質問","question":"５ページのところで5)スクールカウンセラーの派遣とあるんですが、スクールカウンセラーは今も非常にニーズが高くて人材不足だというふうに言われていて、スクールカウンセラー自身の専門性の評価とかそういったところというのは、そのカウンセラーのお仕事ぶりといいますか、当然専門性が高いので、学校の先生やその資格のない方からすると、なかなか判断しにくいと思うんですが、その一方で。","respondent":"渋谷指導課長","answer":"それでそのスクールカウンセラーに対しての、スーパーバイズする学識経験者をお願いしています。具体的にいうと立正大学の中田教授にお願いをしていて、その方からスーパーバイズを受けながら、スクールカウンセラーは資質の向上に努めているです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"高橋委員","kind":"質問","question":"わかりました。そういった形で、カウンセラーの資質の維持、向上に努めていらっしゃるということですね。一般の区民の方が、いろいろ事情があって相談される問題があるとすると、現場の先生方等にどのようにその相談内容を整理して、今後に活かすように提示といいますか、されているというか、していこうとされているんでしょうか。どう活かされるんでしょうか。","respondent":"渋谷指導課長","answer":"今ここでご指摘いただいている教育相談センター、あるいは教育センターそのものの見直しに、この後取り組んでまいる予定ですが、今言った情報共有のあり方だとか、情報をどういうふうにフィードバックして連携を図っていくのかというところについては。","voiceIndex":25,"id":"exchange-011"},{"speaker":"沢田副委員長","kind":"確認","question":"先ほどのところでもう一回確認だけなんですけれど、何度も同じ質問で申しわけありません。評価のコメントは基本的に教育委員のことだという話だったと思うんですけれど、ちょっとその確認をさせてください。これはちょっと細かいことになってしまうんですけれど、「事業廃をも視野に入れた」は、廃止のことですか。〔「「止」が抜けていますね」と言う者あり〕ちょっとその辺も確認させてください。","respondent":"田村教育次長","answer":"輻輳してしまっているので説明をもう一度振り返りますけれど、地教行法の中で、教育委員会というのは事務局でなく、教育委員の集合体を言っているんですね。","voiceIndex":27,"id":"exchange-012"},{"speaker":"大倉委員","kind":"確認","question":"確認で、先ほど３回行って、半日レクチャーを行って、郵送して検討を加えていただいて、会議に出ていただくということだったんですけれども、もう一度、時間はどのぐらいの時間をかけてやるんでしょうか。","respondent":"齋藤庶務課長、田村教育次長","answer":"１回当たり小一時間はかけると考えております。議論の時間を、事業の説明時間を含めて。そのときだけではなくて例えば別の機会でも、こんなことを考えているというお話もいただきます、教育委員から、この事務事業点検以外のときにも。今年など特に考えたのは、長期計画が見直しになったり、自主計画の見直しがあったりすると、あとやはり教育に関する意見交換会で地域に私たちも出ているのでそういう情報を、あとＰＴＡ会長と区長との意見交換会と。","voiceIndex":29,"id":"exchange-013"},{"speaker":"大倉委員","kind":"意見","question":"さまざまなところで情報を出しながら、連携を取りつつやっていく中で、この評価というのは３日間で取りまとめていただいて、出していると。もう６回目ということで、では、例えば１回目、２回目、３回目などはもっと時間をかけてやってこられた中で、今はもうこのぐらいで、いろいろな過去の経験等からこの時間で済んでいるということでいいのか。","respondent":"田村教育次長","answer":"なぜかというと、これだけのボリュームの内容を見るというのは、先生方もそれぞれ別の仕事を持っていますので、ですから表舞台で議論したのが３回であって、それ以外の閉会後、あるいは事前にご自宅にお送りした資料にお目通しいただいて。","voiceIndex":32,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"保育園のところ２３園となっているんですけれども、大体乳幼児数としては何人ぐらいというふうにこれを見たらいいでしょうかというのが一つ。現実的に園で一定の、品川区の保育課としての指導に従ってされていると思うんですけれども、いろいろな意味で親との関係での大変さがあるから、苦情みたいなことというのはあるんですか。もしその中にあったら教えていただきたいという、この２点です。","respondent":"立川保育課長","answer":"それから流行期になりますと、通年で実施していることですけれども、感染症についてはクラスと発症者数を保育園のほうで感染症ごとに人数等を掲示しまして、保護者に注意喚起をしております。","voiceIndex":40,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"１,０００名だとおっしゃったんですが、これは罹患数でなくて、該当したクラスの総数ですよね。私が知りたかったのは、子どもなり保護者の方が、この２３園１０２クラスの中で何人ぐらい発症しているのかという、その数を知りたかったので教えていただきたいということ。一般的にはどういうふうに指導しているというか、対応していただいているんですかね。","respondent":"立川保育課長","answer":"実数ですけれども、クラスで３名以上が罹患した場合に登園自粛を呼びかけているところですが、年齢によってクラスの人数が違いますので、手持ちの資料ではお答えできないところもありますけれども、罹患者数につきましては１月。","voiceIndex":42,"id":"exchange-016"},{"speaker":"南委員","kind":"意見","question":"個別の問題にならないようにちょっと配慮していたつもりなんですけれども、今の課長のお話のような対応にしかならないなとは思うので、あれですけれど。なかなか個別にはいろいろとあるかもしれませんので、それはそれとして受けとめて、資料も含めてお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-017"}]},{"id":"topic-02","title":"の南品川４丁目国家公務員宿舎「品川寮」跡地 認可保育所運営事業者の選定","agenda":"の南品川４丁目国家公務員宿舎「品川寮」跡地 認可保育所運営事業者の選定","exchanges":[{"speaker":"南委員","kind":"提案","question":"教えてください。それから、ほかの４事業者はちなみに、言える範囲でもちろんいいんですけれども、区内事業者がどのぐらいあったのか、あるいはどんなところだったのかというのを教えていただきたいと思います。それから裏面で、審査会がずっと行われて今日に至っているんですが、この審査会のメンバーというのはどういう方々によって構成されているのか、それを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"１点目のご質問ですが、この法人は、どんぐり保育園とみずなら保育園の２園の認可保育園を実施しているところで、事務事業概要のほうにもその２園が記載されているところです。","voiceIndex":50,"id":"exchange-018"},{"speaker":"塚本委員","kind":"質問","question":"選定についてはここに報告されているとおりだと思うんですけれど、この地域への保育園ができますということでの地域住民の方への説明というんですか、事業者選定のタイミングでそういった説明をされる予定なのか、あるいはこれまで説明というのはどういうふうにされてきたのかということを、ちょっとお伺いしたいんですけれど。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちら８月の文教委員会で報告後、それぞれの町会長会議、地域的には品川第一地域なんですが、隣接が品川第二地域になりますので、品川第一地域センターおよび第二地域センターの地区の町会連合会のほうに私が出向きまして、この土地については区が借りる予定であるということと。","voiceIndex":52,"id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"地域の方々の概ねの反応について、教えていただけますか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"それぞれ質疑ということでは、町会のほうとお話ししたときに、まだ待機児童が多いので、待機児童の取り組みについて、品川区は今後どういうふうに続けていくのかというふうなご質問がありました。","voiceIndex":54,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"開所時間が夕方６時半までなんですが、必ずしも夜遅い時間まで開所していることが望ましいとは私は思わないんですが、今は一般的にもう少し、７時半、８時、あるいは１０時、そんな開所時間にしている保育園が多くなっている中で、６時半というのは、この保育園の法人の考え方があるのかなと、わからないですけれどちょっと思うんですが、区としてはこれについてはどのような見解を持っているんでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後その延長時間につきましては事業者と、２時間程度ということでご提案いただいておりますので、協議を進めていきたいと考えております。","voiceIndex":56,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"そうしますと、こちらの法人としては、２時間だか１時間だかはわからないけれども、子どもの保育、親の就労状況を見て、その時点で延長を考えていこうと、そういうことだと理解していいですかというのが一つ。それから区が６時半までと提示したという、そのことがちょっと意外かなと思ったので、そのあたり区のほうの考え方、なぜ６時半にしたのかというところをちょっと伺いたい。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そして園庭の考えですけれども、本事業者の提案では、今、園庭は交差点側にとって、大体１階の屋外遊戯場で１００m2程度の面積をとりたいということで、今後２階、３階の、施設によってはそこも屋外遊戯場としての届け出をするかどうか、今後区と協議をしてまいります。","voiceIndex":58,"id":"exchange-022"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"沢田副委員長","kind":"質問・要望","question":"事務事業評価のところでも、教職員の研修はＡで拡充ということでしたけれど、この研修一覧を見て、区独自研修のところをもちろん拡充、スクラップ・アンド・ビルドを進めていくということが書かれていましたけれども、かなり多岐にわたっていろいろな研修をされていると思うんですが、例えばどういったところを、また新しい研修を入れていくとか、これは今後のことだと思うんですが、いや。","respondent":"渋谷指導課長","answer":"新補転補の教員研修につきましては、市民科が大きな中身になります。特に新補転補の教員研修の第２回目は、市民科の指導計画の作成だったり、実際にそれをどんなふうにやるか、演習をやってもらったりとかということで、市民科に特化したものに取り組んでいるところです。","voiceIndex":65,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"先ほどのご説明では指導教官から指導を受けながらというお話だったと思うんですが、具体的にはこれは、本当に２時間とかいう時間をきちっととって、マンツーマンで例えば面談みたいなことをするんでしょうか。どんな形でやられているのか、ちょっとお聞きしたいと思います。","respondent":"渋谷指導課長","answer":"初任者１名につき、必ず指導教官を任命して、その方を中心に、マンツーマンで指導することもありますし、初任者だったり若手教員を教務主任が集めて話をしたりですとか、生活指導に関するところの部会に参加させたり、形態はさまざまですが、しっかり時間を確保しています。","voiceIndex":67,"id":"exchange-024"},{"speaker":"塚本委員","kind":"質問","question":"それともやはりきちっとした、指導教官から与えられた時間の中で研修を受けたということが、この研修ということになるんでしょうか。","respondent":"渋谷指導課長","answer":"何か明確な達成基準のようなものがあって、それをクリアしないとこの研修は修了にならないとかいうものがあるわけではないです。そういう意味では、きちっと受講をして、指導を受けてとかいうことで、一応研修は修了という形にはなります。","voiceIndex":69,"id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"実際の学校現場で働く中で、いろいろ学ぶことというのが実はいろいろあったりして、そこできちっと経験として積める人もいれば、何となくそういうふうにならなくて流れてしまうとかというのが、何かもったいないじゃないですけれど、そういうところをうまく経験としてしっかり積めていくような仕組みということについて、体制づくりみたいなものの中で、どのように今。","respondent":"渋谷指導課長","answer":"ただ、１年終わっても課題がある先生として認識した者は、２年目についてもそれは継続して指導していくということで、日々そういった人材育成に取り組んでいるというのが実情です。","voiceIndex":71,"id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"今のような中で、もうちょっと生活指導面での力をつけたほうがいいねというふうになったとき、この中にもそういった意味での研修というのはあるのでしょうか。","respondent":"渋谷指導課長","answer":"いわゆるこの方は指導力が足りないというようなことで、指導力不足に対する教員研修というのは、品川区ではなくて、東京都の研修センターのほうでそういったメニューがあります。","voiceIndex":73,"id":"exchange-027"},{"speaker":"塚本委員","kind":"質問","question":"それは多分希望したり、勧められたりして受けたりするんだと思うんですけれど、効果のほどというか、非常に優れたものでしっかり生まれ変わってくるみたいなことが、比較的言えるものなのかどうか。まあ、難しいかもしれないですけれど、一応その感想だけ最後にお聞きしたいと思います。","respondent":"渋谷指導課長","answer":"私の知っている限りだと、ここ３年間は、品川区からいわゆる指導力不足の研修の受講対象になって行った者はおりません。","voiceIndex":75,"id":"exchange-028"},{"speaker":"高橋委員","kind":"意見","question":"二つございまして、一つは特別支援、生活指導力ということで、特別支援の児童・生徒に対する研修も出ているんですけれど、担任の先生方もそうなんですけれど、最近では配慮を要する子たちが普通学級の中にもいらっしゃるわけで、そうするといわゆる担任の先生方以外にも、ここにもちょっと研修が書いてあるんですけれども、それも含めて、そういった状況に対応するために、どういう研修や。","respondent":"渋谷指導課長","answer":"特別支援は、通常学級に在籍する子どもたちへの配慮もすごくスポットが当たっているところでありまして、品川区では、年度がちょっと正確でないですが、おそらく平成１８年度から、全教職員を対象にした特別支援に関する研修会というようなものを実施していました。","voiceIndex":83,"id":"exchange-029"},{"speaker":"高橋委員","kind":"質問・要望","question":"そこでおそらくいろいろな意見があると思うので、そこで「言ったんだけど」みたいな形にならないように、ぜひ改善し、本当に貴重な時間をかけて研修しているわけで、その点、よりよい改善を常にしていただきたいと思いますが、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-030"}]},{"id":"topic-04","title":"続きまして、(2)の委員長報告","agenda":"続きまして、(2)の委員長報告","exchanges":[{"speaker":"高橋委員","kind":"質問・要望","question":"そういうことについて、私はちょっとよくわからないので、どのようにして東京都のほうに要望するかとか、そういうところがちょっとわからないんですけれど、管理職の先生方は大変優秀なので、お２人替わっても混乱はないかもしれませんけれど、そういうことに関して、区として東京都にどんな形で働きかけるんですか。そういうこと、同時はちょっと困るんですけれどみたいな。","respondent":"渋谷指導課長","answer":"委員ご指摘のとおりで、学校現場でいきなり管理職２人が替わるということがないように、都との協議の中では申し入れをしていきたいと考えています。","voiceIndex":96,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4818#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":44881,"voices":98}},{"id":"h26-20140225-5","meetingId":"h26-cm02","date":"2014年2月25日","dateIso":"2014-02-25","committee":"総務委員会","time":"午前１０時００分～午後０時０２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２６年度都区財政調整","agenda":"平成２６年度都区財政調整","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっとお聞きしたいと思います。財調算定で協議が行われたということで、まず伺いたいのは、区でいろいろ主張されて、新規算定もあるわけですけれども、逆に、区がこれは強く言ったのだけれども算定できなかったという主な項目を教えていただきたいのと、消費税が入るのだと思うので、その算定方法はどういうふうに見直されるのか、もし具体的にわかれば、教えてほしいと思います。","respondent":"本城企画財政課長","answer":"それとあわせて、消費税の関係ですが、消費税については、先ほど基準財政収入額のところでご説明させていただきましたが、今回、地方消費税交付金という形で、消費税がアップした分も含めて、交付金という形で区に入ってきますが、それについて算定方法を新たにするということで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば、区の主張の部分でいくと、これだけこういう形で我々の目にも見えるようなというか、どういう協議をしているというのがいつもわからない。細かいことがよくわからない。だから、こっちから主張した協議というのは、多分その１項目だけではないと思うのだけれども、もうちょっと具体的に教えてもらったら、ありがたい。","respondent":"本城企画財政課長","answer":"今後どういう形で、１つの資料としてお出ししたらいいかについては、また改めてよりわかりやすい形にしていく必要があると思いますが、今、口頭でこのような形でご説明させていただきました。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この算定は出てくるので、我々の一番の思いは、例えば、今の話で休日保育などは、所管の２３区の課長会などで、１３区しかやっていないと、我々でも、これは都に言っても標準算定されないのではないのかとイメージとして何となく思ってしまうではないですか。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"浅野委員","kind":"質問・要望","question":"基本的なところからお伺いするかもしれませんけれども、お願いします。１ページの基準財政収入額で、２番で標準徴収率により算定するという部分があるのですけれども、過去の書類などを見ると、９８％という数字が出ているのですけれども、税収は１００％入らないという見方があるのは知っているのですけれども、この９８％というのは毎回固定されているのかどうかということをちょっと教えていただきたい。","respondent":"本城企画財政課長","answer":"１ページ目の標準徴収率ですが、これについては、先ほど９８％とございましたが、特別区民税については９８％という形で見ております。ここは継続的に、実際全額徴収は難しいということがありますので、９８％ということでずっときております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"もう一度伺うことになるのかと思うのですけれども、３ページの投資的経費で、２年連続で通しているという話は、いろいろそういう内容があってと伺っているのですけれども、ここはこういう伸びをしているということは、区としてもここに係る部分というのはかなりあると思うのです。そうすると、全区的には、ここの部分に大きく引っ張られてくるという可能性もある。","respondent":"本城企画財政課長","answer":"平成２６年度は、今ちょっとお話ししたもの等も含めて、そういう影響、検討の中での続けての伸びということが特徴的なポイントかと理解しております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほどの新規算定の主な項目ということで、算定改善ということで挙がっているのですけれども、ここの中で、平成２６年度の都区財政調整協議会結果速報というところを見ると、協議が整わなかった項目が１７項目と書かれているのですけれども、そこら辺の中身を教えていただきたい。","respondent":"本城企画財政課長","answer":"先ほどは民生費を中心にご説明させていただきましたが、経済労働費の中では、創業支援事業についても区ごとの事業費の乖離が大きかったとか、観光振興費関係についても、区ごとの事業費の乖離が大きかったとか。","voiceIndex":14,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ここに書かれているような、２３区は首都の大都市ならではの抱える問題をどう解決していくのかというところでの財調の中でのやりとり、協議があるのではないかと思うのですけれども、そういう点では、例えば、ここにも書かれているような待機児解消とか、高齢者施策とか、そこら辺は、具体的なところはどんな協議になったのかなというあたりをもう一回お聞かせください。","respondent":"本城企画財政課長","answer":"そういったものを反映して、新たに平成２５年度の再調整の中で幾つかの項目を基準財政需要額に加えたところですが、こういった区の意識としての重点課題として捉えているところも防災対策を充実させたり、公共施設を充実させたり。","voiceIndex":16,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２５年度再調整ということで、４２５億円というのが出てきたわけですけれども、例えば、防災対策および子育て支援施策の算定というのが４６億円で、公共施設改築経費の算定が２３４億円ということで再調整の中で出てきているのですが、これはどういう形で算定されるのか、仕組みを教えていただきたいのです。","respondent":"本城企画財政課長","answer":"協議のあり方についてですが、先ほど保育関係の事業とか、かなり細かいところでやりとりがあったということをご説明させていただきましたが、再調整につきましては、東京都の税収見込みがかなり固まって、大きな伸びが見込まれるという見込みがついた段階で改めて。","voiceIndex":18,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう形での子育て支援策と防災対策というのは、算定がどういう仕組みになっているのかというのをちょっと聞きたかったのです。特別交付金３億円は、今後の調整の中でどういうふうに配分されていくかというのが決まっていくということなのですけれども、では、品川区としてはどんな中身で要求するのかというあたりもちょっとお聞かせいただきたいと思います。","respondent":"本城企画財政課長","answer":"特別交付金につきましては、まさに申請の手続ということで、今、手続中ですが、特別交付金の説明の中で、災害等という形でご説明はさせていただきましたが、災害だけではなくて、それらを含めて、基準財政需要額という形で２３区共通のところに盛り込まれていないものでも。","voiceIndex":20,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"特別交付金は、具体的に品川区としてはどういうものを要求していくのかというところを先ほどお聞きしたので、ちょっとお願いします。","respondent":"本城企画財政課長","answer":"災害関係でいえば、いろいろな項目がありますが、例えば、この前、大雪があったときに施設が壊れて、それを復旧する経費とか、災害時に緊急対応しなければいけなかった時間外手当的なものも含めて、緊急対応としてはやっております。","voiceIndex":22,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明があったのにわからなかったのか、わからないのですけれども、先ほどの防災対策および子育て支援施策の４６億円、それから、公共施設改築経費の算定による３４億円ということなのですけれども、これについては、品川区としては積み上げてどういうものを東京都に求めるのかというあたりの中身についても、具体的なところがわかったら教えていただけますでしょうか。","respondent":"本城企画財政課長","answer":"特別交付金のご説明と普通交付金のご説明を混同してしまって、本当に申しわけないのですが、先ほど個別の例を挙げて、こういうのを要求しているというお話をしましたのは、あくまでも特別交付金のほうです。","voiceIndex":24,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"なかなかわかりにくいことなので、何度も聞いてしまって申しわけないのですけれども、２３区統一で、今回改めて再調整という形で出てきた防災対策および子育て支援施策の算定の中身、そして、公共施設改築費の中身というあたりを、今回再調整でこれだけの財調が出てくるのだという具体的な中身をもうちょっとイメージできる形で教えていただきたいというのが、先ほどからの思いなのですけれども。","respondent":"本城企画財政課長","answer":"再調整の中で、総額としては４２２億円ということでご説明いたしましたが、そこに積み上がっていますもので、防災につきましては、防災備蓄経費、それから、災害対策用医療資機材の経費、それから、子育てについては、認証保育所の運営等の事業費について算定するという形で。","voiceIndex":26,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、新規で出てきた中身が再調整でも同じような考え方で出てきているという考え方なのですか。新規での認証保育所運営費等事業費の算定充実ということと、防災の備蓄とかが入ってきていると思うのですけれども、基本的な考え方としては、新規のところに算定されたようなものが再調整の中でも出てくるという考え方ということなのでしょうか。","respondent":"本城企画財政課長","answer":"本来財源が出てきたものに見合って、喫緊の課題が何であるかと照らし合わせた中で、平成２６年度に盛り込んでいたものを前倒しして、平成２５年度の再算定の中にも取り込むということが適切ではないかという判断の中でという形でご理解いただければと思います。","voiceIndex":28,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"都区財政調整の算定を見ていると、市町村民税法人分が１７.４％も増加した。ただ、心配なのは、２３区に人口が流入して、どんどん増えているという状況を鑑みると、今後社会保障費がいずれ急激な上昇をたどるということも考えられますので、公共施設、道路、そちらもありますけれども、算定に対して将来急激に莫大な費用がかかるということを考えて、都にもどんどん要請していってほしいなと。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-014"}]},{"id":"topic-02","title":"平成２６年３月１日付組織改正","agenda":"平成２６年３月１日付組織改正","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"今、兼務というお話だったのですが、これはあくまでも新聞の内容でしかわからない。三鷹市が新聞に載っていて、これは大変幅が広いし、大変だから、あそこは補正予算を組むので少しでも早くやっていく、人員も配置してやっていくと書いてあって、国は地方自治体に投げて、こんな大変なのに、何でこんなことをするのだぐらいのことが書いてあったけれども、今、兼務、あと職員体制も教えてほしい。","respondent":"柏原行財政改革担当課長","answer":"今、組織の中でお話を申し上げましたので、担当課長、担当主査については兼務というお話をさせていただきましたが、品川区といたしましても、全庁で対応していくということで、既にプロジェクトチームを立ち上げておりまして、先ほども申し上げましたけれども。","voiceIndex":36,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"意見だけにします。これはよくわかっていないで言っているのですが、どれぐらいの規模で全庁的に大変かというのは、何かいろいろ皆さん、新聞等で大変だというのが書いてあるけれども、全庁挙げてみんなそれぞれが協力体制をとるというのはいいのだけれども、通常の仕事もされているわけだから、職員は大変だなと思うぐらいで、その辺は本当にうまく整理してやっていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"臨時福祉給付金と子育て世帯臨時特例給付金の支給対象者は、子育て世帯臨時特例給付金のところには２万４,９００人というのが見つかったのですけれども、トータルで何人ぐらい対象者がいる事業なのかというところと、いつぐらいまでこの事業の忙しい時期がかかるという想定なのか、そこら辺と、あと先ほど委託するとちょっと聞こえたような気がしたのですけれども、委託であれば。","respondent":"柏原行財政改革担当課長","answer":"今後の事業のスケジュール観ですが、まず非課税の方が対象になるということで、税情報が確定しませんと、その先に進むのはなかなか難しいということがありますので、今のスケジュール観で申しますと、年度明け６月ぐらいから支給の事務に入れればとは思ってあります。","voiceIndex":39,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そんな中で定数を減らして、より大変になるのではないかという思いが、あえて定数を減らしてという感じが、これだけのことがわかっていながら、何でそんなふうになったのかという思いがしているのですけれども、そこら辺の仕事の職員体制という点では、すごく繁忙になってしまうのではないかと危惧されるのですが、いかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"人数の部分というのは、委員のお話の部分はありますけれども、ちょっと繰り返しになってしまいますが、今回の事務で一番難しいところは、前回の定額給付金のときは、区民の方全員ということで、広くということだったのですが、今回の難しいところは。","voiceIndex":41,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これだけの大変な事務というところで、職員に対しての過重な負担にならないように、対応をぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-019"},{"speaker":"つる副委員長","kind":"質問","question":"今プロジェクトチームを立ち上げてとありましたけれども、全国のいろいろな自治体から国を含めて対応について大変であるという今ここで出た意見のようなこと、やはり施策としていって、対応があると思うのですが、一番の課題というのは、いわゆる個人情報で、庁内であったとしても、所管で押さえている情報を共有できるできない、また提供できるできないという中で、プロジェクトチームを立ち上げて。","respondent":"柏原行財政改革担当課長","answer":"それ以外の部分でも、住民基本台帳の情報とか、個人的な表に出してもらっては困るような情報とかにも配慮するようにということで、マニュアル的なものも来ていますので、それを全庁で共有しながら、しっかりと対応していきたいと思ってあります。","voiceIndex":44,"id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問・要望","question":"国からのそうした通達がおりたというのは、報道ベースとか、ホームページ等で確認はしているのですけれども、細心の注意でやっていただくことが一番いいかなということ、あと先ほど委員からの質疑にあった委託の部分で、コールセンターとかありましたけれども、そういった部分で委託になることに当たって、今ご答弁いただいたような個人情報の観点がケアされているとは思うのですが。","respondent":"柏原行財政改革担当課長","answer":"一部では国からの、３月ぐらいから支給できればしてもいいという話もあるのですが、何せ基本的な情報が決まらないことには、かえって混乱を招くというところがありますので、我々としましては、きちんとした情報管理をして、できた情報の中でスムーズに。","voiceIndex":46,"id":"exchange-021"}]},{"id":"topic-03","title":"本日は、所管事務調査といたしまして、都区制度のあり方","agenda":"本日は、所管事務調査といたしまして、都区制度のあり方","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"とは言いながら、品川区はこうやっていきたいと言っても、それが実現するのは、あり方検討会で議論されることだと思うのですけれども、これを見ても、今ここに、項目一覧ということで５３項目は移管ということなのですが、あと１０ページを見ますと、特に役割を見直す方向で検討するというのが３０項目と、役割見直しの是非を引き続き検討するのが１０１項目と、１３０項目ぐらいあると思うのですけれども。","respondent":"桑村企画部長","answer":"私どもとすれば、児童虐待の問題で、児童相談所と子育て支援センター２つの機関があるということで、児童の虐待に対して対処できないのだということで、これをまず１つの突破口にしたいということで、これについては一定の協議を進めています。","voiceIndex":52,"id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど企画部長からもご答弁があったように、児童相談所に関しては早急に品川区に移管していただきたいという思いがありますので、とはいえ、それが移管できると、ほかができるというわけでもないと思うので、区長をはじめ、品川区の力強い発信力のもとに闘っていただきたいと思っていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"お聞きしたいのは、今、部会ができたり、とりあえずいろいろやることをやろうというので、あり方研究会も含めて、報告書も出てきたのですよね。ただやりました、ただつくりましたか、そうではなくてこれを踏まえて、今言ったいろいろな協議に対して突破口を見つけようとされるのか、この扱いというのはどうお考えなのか。","respondent":"桑村企画部長","answer":"私ども特別区側とすれば、これはこれで考えていただくとして、今までやってきた都区のあり方検討の結論が出ているものについて、合意しているものについては早く、都区の協議の中で移管していくんだという考え方なのだろうと思います。","voiceIndex":55,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで、複合化なり何なりを何区かで一緒にやっていったほうが都民にとっていいことではないかという書き方があったのだけれども、これはどっちの方向へ行くと思われるか、ちょっと教えてもらいたいと思って。","respondent":"桑村企画部長","answer":"品川区の立場というのは、はっきり言えば、１つのところで既に完結させたいという形で、その意味では、何区かと一緒にやるということは、東京都がやるのと変わらないのではないかという議論に対して対抗できないだろうと判断しています。","voiceIndex":57,"id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問","question":"これで最後にします。今の話を伺ってわかったのは、もう当初から横串議論があって、２３区がしっかり横串を通してもらって東京都に臨むというところからスタートしていたと思うのです。","respondent":"桑村企画部長","answer":"正直、私の立場からなかなか難しいところがありますけれども、東京都は確かにそういうことを考えられていると思います。","voiceIndex":59,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1976#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":37761,"voices":74}},{"id":"h26-20140226-14","meetingId":"h26-cm02","date":"2014年2月26日","dateIso":"2014-02-26","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時４４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査、受益者負担に関すること","agenda":"特定事件調査、受益者負担に関すること","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"今あらあらの数字で言ってくれて、それはそれでいいんだけれども、それらをもう少し精査した資料を出してもらえると、もう少し中身にいろいろ突っ込んだ話ができるので、今減免している、それから区民の利用、いろいろなものを見ながらどうあるべきだというのを僕は議論したいと思っていたんだけれども。出るかどうかわかりませんけれども。そのあたりを見せていただきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点では、やっぱり減免のもたらす意味というのはすごく大きいんじゃないかなというふうに思っているんですけれども、その点で減免効果というんですか、減免の持つ意味というのかしら、その辺をどういうふうに見ていらっしゃるのかをちょっと教えていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、減免の金額のバランスといいますか、あくまでこれは施設、運用している部分ありますので、そういったところとの兼ね合いというのは、バランスは考えていかなくてはいけないところであろうと思いますが、施設の設置の目的を達成する意味合いからいいますと。","voiceIndex":9,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、私はもっと区民以外の方との差を大きな施設、目的によっても違うけれども、設けているということで、大体が減免としては５割減免、半額免除ということが主だというふうに見たんですが、障害者団体とか、高齢者団体とか、特にきちんとした対応を必要としている団体とみなして、そういうふうに高齢者団体、障害者団体は全額免除というふうになっているのか。","respondent":"柏原行財政改革担当課長","answer":"ただ、そうはいいながらも、より使いやすく、使っていただくためにその本来の目的のために使っていただくというところで、例えば金額面で配慮しなくちゃいけない部分がある部分であるとか、それから、例えば区民以外の方であれば１.２倍とか、そういう設定を、差異をつけながら。","voiceIndex":11,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"決してそうだというふうに言っているつもりはないんですけれども、そういうことになったらそれこそ絵に描いた餅であり、宝の持ち腐れであり、財政効率が悪い、そういう施策になってしまうわけですから、やっぱりきちんと区民の皆さんに活用していただくことが大事であり、一つ一つの施設の中で採算をとっていこうという、そういうスタンスじゃなくて、やっぱりいっぱい活用してもらう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"基本的なところで伺いたいんですけれども、減免規定の有無についてなんですが、その建物が建設をされた、設立をされた経緯というか、目的から、減免というのも、減免の理由というのも決まってくるというのは何となくわかるんですけれども、例えば官公署とか公益団体について、あるところでは全額免除している、あるところでは半額免除している、またあるところでは全くそういう記述がないという。","respondent":"柏原行財政改革担当課長","answer":"単にこの目的以外のことで官公署が、例えば何かこう集会的なところとか説明会的なところ、公益なところで使うのではあるんですが、その文化、スポーツ、レクリエーション、そういったところに寄与するといいますか、そういった目的ではないということになりますと。","voiceIndex":14,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"例えばきゅりあんなんかが、この前正月に賀詞交歓会ありました。区主催の賀詞交歓会ありましたけれども、ああいったときは、じゃあ料金を払っているということなんでしょうか。特に官公署とか、それとはまた別に条例があって、それは減免されるということになっているのか、その辺について伺いたいと思います。","respondent":"工藤総務課長","answer":"新年賀詞交歓会の件ですので、私のほうからお答えします。こちらの場合には会場使用料という部分は区のほうでお支払いしていることです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問・要望","question":"ちょっと不勉強で確認させていただきたいこと、その他幾つかお伺いしたいと思います。できればお伺いしたいと思ったんですが。それから減免ということで、減免が８割という、先ほどお話を伺って、ああかなりのものだなと思ったんですけれども、減と免って随分違うと思うんですよね。その辺何か課題意識として持っていらっしゃるかどうかをお伺いしたいと思います。とりあえずここまで教えてください。","respondent":"柏原行財政改革担当課長","answer":"これは稼働率というのはそれぞれの貸出しのコマですね。午前、午後、夜間と、このコマを１コマと考えて、それを全体でやったときにどのコマが埋まったかと、その分母、分子の関係なんですが、約１７％、１８％ぐらいですかね、稼働率がこうなってあります。","voiceIndex":18,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"だから、例えばこういう考え方を入れるのであれば、今後は文化センターなども2)にあるような考え方を入れていくのかとか、何かこう区の中で、何といったらいいんでしょうか、減免の考え方が施設ごとに異なっていて、設置目的が違うところが違うのは構わないんですけれども、そうすると、じゃあスクエア荏原というのはほかのところと全然違った設置目的じゃなかった、そうでもないと思うんですよね。","respondent":"柏原行財政改革担当課長","answer":"すみません。ちょっとわかりづらい説明で申しわけございません。委員もおっしゃっていただいたあれなんですけれども、こちらのほうの荏原平塚総合区民会館はきゅりあんと同じ総合区民会館と、まずそういう大きな位置づけであるということです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"そろそろ終わりたいと思うんですけれども、１件気になっているのが、減免の考え方でどこが使うかという、その主体によって減免していくものと、それから社会教育のためとか、何とかのためというか、一応団体は区切っているけれども目的というものを重視してやっているものとあると思うんですね。減というものを取り入れていくというような考え方もあってもいいのではないかと思うんですが、いかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"その対象になるという対応をしているというふうには聞いてありますので、その点は少しサークル的なのが何なのかというのはちょっとあれですけれども、やっぱり使用の目的の部分でどういう形態になるのかというところを、例えば集会所ですと。","voiceIndex":24,"id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これどっちも正しくて、その背景には曜日と時間帯も十分、あと部屋の種類、１つの大きな館でいうのではなくて、その館の何の部屋なのか、目的によって全然色彩が違うような気がしていますので、これをまず冒頭で要望としてさせていただきたいと思います。あれだけ５つも部屋を用意して、すごい稼働率であり、それでもいっぱいなぐらいだと。行革ですから、先ほど来の課題の中で、じゃあいつ改修するんだと。","respondent":"柏原行財政改革担当課長","answer":"特に公共施設の有効活用プラン等々でも方針を示させてありますけれども、場合によってはその施設の複合化であるとか、統合化とか、いろいろなことも視野に入れながら、より使いやすいものにしていくという考え方だろうというふうに思っております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ありがとうございました。他の施設で老朽化であるとか、来るべきそういう時期を待つ姿勢ではなくて、これは要望でいいんですが、現状これだけの利用率がかけ離れているケース、大きく乖離している施設、利用率が乖離しているようなところには、待つのではなくて手を入れる積極的な、戦略的な改修というのは、１つテーマにしてもらいたいと思います。これも後でご答弁ください、やはり。私自身も感じています。","respondent":"柏原行財政改革担当課長","answer":"ただ、いずれにしても、繰り返しになってしまいますけれども、わかりづらさとか、そういった課題があるというのは認識をしていますので、いろいろな部分では検討はしていきたいというふうに思っております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問・要望","question":"近くにやはり荏原第５地域センター等があるという中で、例えば大きな規模の部屋なんかに限らず、同趣旨の、何というんですかね、同規模のものが仮にずっと稼働率が高いと。全然とれない状況だと。でも、片や中小企業センターは同じ曜日、同じ時間であいていると。特に土曜日なんかだそうなんですが。そのときに、それをどう考えるか。片一方は。もう片一方はとれない状況だと。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"いろいろご説明いただいて、ほかの委員からも話があって、１つちょっと疑問に思ったところをまずお聞きしたいんですけれども、区民集会所ですね。８割以上が減額か免除になっているというご説明だったと思います。でも、この地域住民主体のサークル団体というので、何らかの登録がされない。あっ、そうかそうか。じゃあそれはすみません。最初の２割というものがどういう人たちが利用しているのか。","respondent":"柏原行財政改革担当課長","answer":"具体的に個別にどういった内容を使っているかというのはちょっとあれなんですけれども、先ほど申しましたように、いわゆる有料扱いで集会所を使っている方たち、２０％弱ぐらいいらっしゃるようです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"最初の質問とちょっと関係して、それを聞いた上での質問だったんですけれども、要は区民でない方の利用がそれなりにあるというふうな考えなのかなとは思っていたんですが、いわゆる社会教育関係団体の登録があって、集会所利用の登録というのがあるんですかね。２人であろうが、３人であろうが、４人だろうが。いわゆる１割強は区民以外の利用なのかななどと思ったりした。","respondent":"柏原行財政改革担当課長","answer":"確かに、例えば施設のあり方、施設の考え方で総合区民会館と集会所で、そのまま同じルールで議論するのはなかなか難しい部分がありますが、ただ２割増しが本当にこのままでいいのかどうかというのは、１つ検討する材料といいますか、視点であろうというふう思います。","voiceIndex":34,"id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"いろいろ考え方があって、その設立目的というのもさまざまあって、それも十分わかります。しかしながら、やはり使っていただくのはというか、使う目的があって使う側は使うわけですから、それに対して、やはりゼロということはまずないので、しかるべき利用料というのは今後も取り続けていくと思うんですけれども、何が言いたいかというのがちょっとわからなくなっちゃった。要望で終わります。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"渡部委員とかぶる部分もあるかと思いますけれども、お伺いしたいことがありまして。区内全域で。渡部委員も夜間の料金のお話を質問されましたけれども、どうして変える必要があるのかなというのが１点、ちょっと教えていただきたいと思います。さまざまな意味があるかと思いますけれども、その点を１つ教えていただきたいと思います。その点についてちょっとお伺いできればと思います。","respondent":"柏原行財政改革担当課長","answer":"考え方ですけれども、おおむね集会所、文化センター等々につきましては、これについては、大体普通の集会室的なところは平米単価、１時間、６円から９円ぐらいの間に設定をしています。","voiceIndex":37,"id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"それが適正かどうかというのはまた別な話になるかと思うんですが、午前、午後、夜間で利用状況ですかね。これは私の意見なんですが、少し外れていたら申しわけないんですけれども、この利用料の全体の収入ですね。収入というか、収益というんでしょうか、売り上げといいましょうか。今出なくても、出るのであればご答弁いただきたいですし、出なければまた後日にでも出していただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"直近の新しいデータということでは、ちょっと手元にはないんですが、若干古いデータで申し上げまして、維持管理に係る経費、ただ、この維持管理の経費のとり方というのはなかなか難しい部分がありますので、例えばその施設の改修をして。","voiceIndex":39,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問・要望","question":"３割から４割ということで、この数字が適切とか、そういうことは私はちょっと申し上げる気はありませんが、やはり趣旨としましては区民の方にこういう場を提供して、活発に活動していただきたいという地域としての活動、また文化、教育、スポーツという観点からやっていただきたいということ、これからも進めていっていただければと、そのように思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"短くしたいと思いますが、この受益者負担に関すること、今後資料もいただけるということなんですけれども、検討の機会が本委員会中にあるのかどうなのか、それはこれから正副委員長にお任せしたいと思うんですけれども、ここで今日議論した、あるいは次回資料をいただく、何かこう、それだけの余裕があって言っていることなのかどうなのか、全体の中での位置づけをどうお考えになっているか、これは委員長に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-019"},{"speaker":"須藤委員","kind":"意見","question":"もう検討する時間がないということなので、今日出てきた話聞いていると、免除ということ自体にいろいろ課題が今後あるんじゃないかというような話がちらっと出ているのと、施設によってこの減免の仕方だとか、区外の人の料金プラスだとか、いろいろな面でいろいろ考えてもう１回やっていきましょうというのが行革委員会の中で、もう少しその辺を突っ込んでやりたかったんだけれども。","respondent":"山元委員長","answer":"そういう意味で本当に時間のない中でいろいろご意見いただきましたので、皆様から今日いただいたご意見等は、次回の、先ほど申し上げましたように、行革になるのか、また、その所管の委員会なのかは定かではありませんが。","voiceIndex":46,"id":"exchange-020"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"全体的なやり方、まとめ方としては正副のお考えで、私はそれでいいと思うんですけれども、中間まとめをあれだけたたいて、自民党さんからもご提案があって、「総合評価方式の本格実施に向けて」ということで、中間まとめという形でわざわざ当委員会であれだけ徹底的にやって、中間まとめという形で今回は参考についていますけれども、最後に出てくるまとめというのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-021"},{"speaker":"あべ委員","kind":"意見","question":"４つの調査項目という非常に多い数の中で、委員長始め、大変ご苦労されたと思います。ここで改めて敬意を表したいと思います。特に最初のころから４つは難しいという話が出ていて、かつ、出てきたらという話だった公有地もかなり、いろいろ視察も含めてやることによって、いよいよ無理になってきてということだと思うんですよね。それは私の現段階での意見ではありますが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-022"},{"speaker":"南委員","kind":"提案","question":"やっぱり１日かけてしっかり提案された項目を、みんなそうだ、そうだと思ったから出したんだと思うので、そういう意味ではやっぱり時間はなくはなかったというふうに思うし、足りなければつけ足すことだって、新たな日にちを設定することだって、委員長の裁量としてできるわけですから、それがなかなかいろいろな状況があって大変なところはあるけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"正副のほうでまとめていただくのは賛成であれですが、今あくつ委員のほうから言っていただいたとおり、やはりあれだけけんけんがくがくしました中間まとめが出ていますので、まず１つはそちらのほうを参考にまとめにも上げていただきたい。もともとの調査項目にはなっていましたので、載せていただけるのであれば載せていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"確認","question":"順番だけ確認なんですけれども、今日これで、次回にまとめが出てくるんですか。正副委員長から。その次回の委員会の流れを考えていったときに、そのまとめだけで終わってしまうのか、今日やっていたものを引き続きやっていけるのか、そこら辺も検討しておいてもらいたいなと。","respondent":"山元委員長","answer":"そして先ほど、若干、渡部委員からも出ましたいろいろなご意見、受益者負担に関するものもありましたけれども、それをまとめて、一応次回は皆様に正副でまとめたものを見ていただいて、そしてそこでまた議論を、よしとか、ここはどうというご議論をしていただいて。","voiceIndex":61,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"意見","question":"だから、先ほど言った資料が出るし。その資料ができるし、４月、５月、あと２回あるわけですね。今のだと委員会が今日で質疑全部終わっちゃって、この次からはまとめで１回やって、最終回は提出するだけみたいな、そんな雰囲気に聞こえてしまったんだけれども、もう１回ぐらい審議して、その審議がまとまらなくていいと思う。ただ、そういう審議の時間というのはするべきじゃないかなと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5962#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":36306,"voices":66}},{"id":"h26-20140227-17","meetingId":"h26-cm02","date":"2014年2月27日","dateIso":"2014-02-27","committee":"震災対策特別委員会","time":"午前１０時００分～午後４時５０分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"簡単なことですけれども、先ほどから品川区の防災センターと比べていただいているので、それで質問なのですけれども、広さ的に随分違うのかと思うのですが、どのくらい違うのかとイメージ的に準備しておきたいのでお願いします。","respondent":"鈴木防災課長","answer":"それと、本所のほうは、１階のところは大きくエントランスホールがありまして、そこでコースを体験する方へのガイダンスをしたりというところがあったり、そのためのライブラリーの部屋がありますので、品川区のシアターにない機能も持っているので。","voiceIndex":6,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"陳情について、区で用意した資料の説明はあったのですが、要するに、陳情項目１、２、３について、区はどう考えているのか。通常、そこが冒頭に触れられると思ったのですけれども、資料についての説明だけだったので、まだ所管課が来ていないからあれかもしれませんが、陳情項目について、まず、区はどう考えているのか、そこの説明が先だと思いますので、よろしくお願いします。","respondent":"鈴木防災課長","answer":"この陳情項目１、２、３につきまして、区の考え方をというご質問ですので、まだ主管課長が見えていないところがあるので、防災課で答えられる範囲でということで、お答えをすることでよろしいでしょうか。","voiceIndex":15,"id":"exchange-002"}]},{"id":"topic-02","title":"その他」を議題に供したいと思います。 まず、(1)の「議会閉会中継続審査調査事項","agenda":"その他」を議題に供したいと思います。 まず、(1)の「議会閉会中継続審査調査事項","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"本日もらったので、もう少しよく見て、追加の意見は追加で提出したいと思いますけれども、５ページの下の丸の４つ目、２項道路のセットバックの問題ですけれども、違反建築物件とありますが、法律が後からつくられてきて、つくった当時は合法だけれども、今の法律からは合わないという点では、行政のほうも既存不適格という言い方をしているかと思うので、そこの言葉は調整が必要かと、この点だけ指摘して。","respondent":"鈴木（ひ）委員長","answer":"今は、皆様から、委員会としてまとめを出すかどうかというご意見をまずお伺いして、委員会でまとめを出していくということになれば、本日、皆様のところにお示しをさせていただきました文書に、会派として、加えるものはどういうものがあるというようなことですとか。","voiceIndex":24,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"この１年間いろいろ議論してきましたので、議会のほうからすれば、特別委員会のほうからしっかり意見を求めておいたほうがいいと思います。そのために議論してきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"８月のときも指摘しましたが、阪神・淡路大震災から１９年目、東日本大震災から３年目、区域内からも繰り返し求められていますので、一体いつできるのか、改めてこの点を伺いたいと思います。ですから、現状における要援護者の防災計画について、パンフレットをつくったり、説明会を開催して、内容、今の計画を伝えたりすることはすぐにできる対策だと思いますけれども、いかがでしょうか。","respondent":"鈴木防災課長","answer":"そのプランにいつから取り組むのかということにつきましては、今申し上げましたように、説明があったばかりですし、改正された法の部分が、今年４月１日施行の予定とされておりますので、平成２６年度に入りましたら。","voiceIndex":31,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"災害時要援護者は、区の長期計画ではどう位置づけられているのか伺いたいと思うのです。やはり、東京で起こったとき、私たちはどうなるのか。二次避難所の設置についても、新たに保育園等を指定していくと２年前の改訂で定められましたが、改訂時はシルバーセンターなど１９施設ですけれども、新たに保育園等の指定とは、現在どこが指定されたのか、どこの保育園なのか、具体的に伺いたいと思います。","respondent":"鈴木防災課長、永尾高齢者福祉課長、中山障害者福祉課長","answer":"先ほど申し上げましたように、今回の法改正で区の要援護者の方への取り組みについての大きな柱として、避難行動時における支援、それから。認知症の方につきましては、やはり本当に認知の能力が落ちていますので、こういう状態になったということも理解できないし、また。３.１１を受けて、障害者の方から実際にいただいた声をご紹介します。これにつきましては、平成２６年度予算のお話ですので、大まかなことしか申し上げられませんが、各避難所連絡会議の活動の支援ということを。","voiceIndex":33,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭に長期計画での位置づけも聞きましたけれども、要するに今の長期計画の素案では、災害時要援護者支援プラン策定は位置づいていないということでよろしいのでしょうか。内部的な協議の範囲ではないのかと私は思うのですけれども、どういうふうに進めようと思っていらっしゃっているのか、冒頭に言った決意や姿勢も私は問われると思うのですけれども、その辺も改めて伺いたいと思います。","respondent":"鈴木防災課長","answer":"１点目の、東日本大震災での実際の被害に遭われた方の状況、また関連死について等を真剣に受けとめて取り組む気持ちがあるのかですが、区としましては、当然そういう教訓なり、また、その後新たに出ました知見も含めて、しっかりと取り組むことで。","voiceIndex":38,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭に、震災の教訓にしっかりやっていきたいとお話がありました。だから、長期基本計画になぜ位置づいていないのですかと伺ったのです。先ほど、災害時要援護者支援プランは、長期基本計画に位置づいていないということですかと伺ったのですが答弁がありませんでした。そもそも避難所ごとにどれくらい発生し得るのか、そういう想定というのは、今、されているのかどうかも伺いたいと思います。","respondent":"鈴木防災課長","answer":"これは先ほど申し上げましたように、長期計画の見直しをかけている途中に、法の改正であったり、国の説明が来たりということで、長期計画に具体的にこの文言を入れ込む段階では詳細が来ておりませんでしたので、織り込んではおりませんが、ただ、防災対策はさまざまな。","voiceIndex":42,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"在宅にいられる方もいらっしゃいます。先ほどどこに相談したらいいのか、窓口はどこなのかというのも答弁になかったので、そこも改めて伺いたいと思うのですけれども、さらに残りの３分の２や半分の方、在宅で高齢者や障害のある方で避難生活をされる方、震災時に支援の申し込みはどこに行ったらいいのか、いや、震災が起こる前に、全員どこに登録しておけばよいのか、そこをご説明いただきたいと思います。","respondent":"鈴木防災課長、永尾高齢者福祉課長、中山障害者福祉課長","answer":"先ほど申し上げましたように、それをこれから、平成２６年度、国からの詳細が示されたものを踏まえて取り組んで検討をしていくという段階ですので。その状態に応じて、ふだんから用意しておくことだとか、どういうものを持っていったらいいかとか。震災前の相談というところでも、同じく区ですとか、あるいは３カ所ある相談支援センターを中心に障害者の方のご不安にお答えしていきたいと考えています。","voiceIndex":44,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"要するに、いろいろ伺いましたけれども、計画の体系も、問題も、整理も、まだまだされていないというのが現状ではないでしょうか。やはり被害を防いでいく、それによって、発災後の避難所や、支援や、それも整っていくと私は思いますので、何よりも被害を防いでいく取り組みに力を注いでいくと、今回の震災を経験して、そういう決意で取り組んでいただきたいと思いますけれども、いかがでしょうか。","respondent":"鈴木防災課長","answer":"人災というお話ですが、この災害時の直接被害ではなくて、事後の関連死のことをおっしゃっているのだと思いますが、この関連死につきましては、先ほど申し上げましたように、国の指針で示された避難所における良好な生活環境の整備というのが示されておりますので。","voiceIndex":48,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかし、阪神・淡路大震災から１９年、東日本大震災から３年、区の長期計画改訂からも２年たって、向こう５年の長期計画見直しの中にもしっかりと位置づいていないということでいいのかと、私は率直に思うのです。やはり必要だと思うのであれば、今はまだ素案の段階ですから、位置づけることは十分可能だと思いますので、その点だけ改めて伺って、ぜひ実施を求めていきたいと思いますが、いかがでしょうか。","respondent":"鈴木防災課長","answer":"この長期計画の内容につきましては、防災課長１人の権限でどうこうできるものではございませんので、これ以上の回答は控えしますが、区の考え、姿勢としては、しっかりと要援護者の方への支援対策についても取り組んでいくということが現在の考え方です。","voiceIndex":50,"id":"exchange-011"},{"speaker":"伊藤副委員長","kind":"質問","question":"だけれども、今、国の中央防災会議がいろいろな知見を集めてやったとしても、現実の問題として、地震の被害を正確に把握することは困難であるということ。だけれども、現状の仕組みの中で最大限の努力をしていくことで、被害を最小限に食いとめていくことが最も大切だと思うのですが、いかがでしょうか。","respondent":"鈴木防災課長","answer":"区としましても、限られた仕組みや資源、財源、人材、全てのものを投入することで、また、それを工夫することでよりよい仕組みをつくって、少しでも区民の皆様の被害を減らして安全・安心に、その中で、災害時要援護者の方も当然、しっかりと対策を組んでいく。","voiceIndex":55,"id":"exchange-012"},{"speaker":"中塚委員","kind":"意見","question":"何をやるのか、どうやるのか、そのためにどんな準備をしていくのか、その計画がまだできていないという問題なのです。つまり、この計画では足りないでしょうという議論ではなく、そもそもどう支援していくのか、何が起きるのか、防ぐにはどう支援していくのか、それにはどんな準備が必要なのか、その計画そのものができていないことが、本日のこの災害時要援護者プランの議論だと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問・要望","question":"この陳情につきまして結論を出していただきたいと思います。態度につきましては、先ほど伊藤副委員長からお話がありました、災害対策基本条例では、自助、共助、公助なのです。〔「計画がないのだよ」と呼ぶ者あり〕 やはり現在進めている自助、共助、公助を進めていくというふうに私は受け取りましたので、態度としては不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-014"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出してください。我が会派としては、先ほどの区のご答弁も聞かせていただきながら、個別にずっと対応して下さってきていたということがよくわかりましたし、社会福祉法人のほうとも連携をとってやって下さっている。そうしたことから、本陳情に対しては、私どもは、区がこれからもやる姿勢はうかがえましたので、個別の計画もしっかりしていただくこともお願いして、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"本日結論を出すということで、私たちもさまざま今お話を伺っている中で、品川区のほうでも、いろいろな想定をして、いろいろな視点から取り組みをしていく。そういった中で、個別具体的にこうするというよりも、しっかりと想定を考えていただく中で、取り組みをしていただいたほうがいいということで、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-016"},{"speaker":"吉田委員","kind":"意見","question":"我が会派も結論を出したいと思います。態度につきましては、やはり個別にやってきている、区としても最大限の努力をして、これからやっていくものだと言われたと思いますので、そういう区の態度はよくわかりましたので、結論としては不採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということで、採択すべきだと思います。先ほどから、何だか公助ばかり求めているというふうに私には聞こえるのですけれども、防災計画をつくるのは自治体の役割です。ですから、目の前にあるこの緑の地域防災計画も自治体がつくるのです。今ある計画の説明、また、今の資材だけでは足りませんから施設の充実、どれももっともだと思いますので採択すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6448#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":28796,"voices":68}}]);
